#[test]
fn fixed_hidden_treasure_found_bytes_derives_from_treasure_count() {
    // formats/saved-gam.md §11: each fixed-hidden-treasure
    // has one bit in the found-bitmap; the bitmap rounds up
    // to the nearest byte. Anchor FIXED_HIDDEN_TREASURE_
    // FOUND_BYTES to ceil(FIXED_HIDDEN_TREASURE_COUNT / 8)
    // so the found-bitmap byte count tracks the treasure
    // count.
    assert_eq!(
        FIXED_HIDDEN_TREASURE_FOUND_BYTES,
        FIXED_HIDDEN_TREASURE_COUNT.div_ceil(8),
    );
    assert_eq!(FIXED_HIDDEN_TREASURE_FOUND_BYTES, 15);
    assert_eq!(FIXED_HIDDEN_TREASURE_COUNT, 113);
    assert_eq!(SAVE_FIXED_HIDDEN_TREASURE_FOUND_OFFSET, 0x02b6);
    assert_eq!(
        SAVE_FIXED_HIDDEN_TREASURE_FOUND_OFFSET + FIXED_HIDDEN_TREASURE_FOUND_BYTES - 1,
        0x02c4
    );
    assert_eq!(SAVE_FIXED_HIDDEN_TREASURE_DAILY_COOKIE_OFFSET, 0x020c);
    // formats/saved-gam.md §10, record 15: "`0x0241` - the equipment
    // counter for item id `39`, the Glass Sword - is also the gate for
    // fixed hidden-treasure record 15. It is the same byte, not a
    // parallel cookie." The engine used to declare a dedicated
    // SAVE_FIXED_HIDDEN_TREASURE_SINGLE_USE_COOKIE_OFFSET at the same
    // address, which is exactly the withdrawn reading; the gate is now
    // derived from the equipment block so the two cannot disagree.
    assert_eq!(SAVE_FIXED_HIDDEN_TREASURE_RECORD_15_GATE_OFFSET, 0x0241);
    assert_eq!(
        SAVE_FIXED_HIDDEN_TREASURE_RECORD_15_GATE_OFFSET,
        SAVE_EQUIPMENT_STOCK_OFFSET + EQUIPMENT_ID_GLASS_SWORD
    );
    assert!(
        (SAVE_EQUIPMENT_STOCK_OFFSET..SAVE_EQUIPMENT_STOCK_OFFSET + EQUIPMENT_COUNT)
            .contains(&SAVE_FIXED_HIDDEN_TREASURE_RECORD_15_GATE_OFFSET)
    );
    // hidden-treasures.md §2 record 14 / time.md §8: the daily
    // cooldown cookie's factory value is ZERO, which matches no
    // calendar day (days run 1..28), so the record is available on
    // the first search. The byte reaches the save image, so an
    // out-of-band 0xFF sentinel would diverge from the original.
    assert_eq!(FIXED_HIDDEN_TREASURE_DAILY_UNSEEN_DAY, 0);
    assert_eq!(RARE_REAGENT_HARVEST_UNSEEN_DAY, 0);
}

#[test]
fn active_object_field_offsets_chain_sequentially() {
    // formats/saved-gam.md §11: per-record active-object
    // field offsets pack contiguously 0..=7 (TYPE / TILE /
    // X / Y / Z / DEP1 / PHASE / DEP3). Anchor each
    // successor to the chain so adding or reordering a
    // field only happens in one place.
    assert_eq!(ACTIVE_OBJECT_FIELD_TILE, ACTIVE_OBJECT_FIELD_TYPE + 1);
    assert_eq!(ACTIVE_OBJECT_FIELD_X, ACTIVE_OBJECT_FIELD_TILE + 1);
    assert_eq!(ACTIVE_OBJECT_FIELD_Y, ACTIVE_OBJECT_FIELD_X + 1);
    assert_eq!(ACTIVE_OBJECT_FIELD_Z, ACTIVE_OBJECT_FIELD_Y + 1);
    assert_eq!(ACTIVE_OBJECT_FIELD_DEP1, ACTIVE_OBJECT_FIELD_Z + 1);
    assert_eq!(ACTIVE_OBJECT_FIELD_PHASE, ACTIVE_OBJECT_FIELD_DEP1 + 1);
    assert_eq!(ACTIVE_OBJECT_FIELD_DEP3, ACTIVE_OBJECT_FIELD_PHASE + 1);
    assert_eq!(ACTIVE_OBJECT_FIELD_TYPE, 0);
    assert_eq!(ACTIVE_OBJECT_FIELD_DEP3, 7);
}

