#[test]
fn save_inn_registry_offset_anchors_to_roster_and_record_len() {
    // formats/saved-gam.md §3: the inn registry view starts
    // at the inn-marker byte of the first character record.
    // Each character record is SAVE_CHARACTER_RECORD_LEN
    // bytes wide; the inn marker sits at the last byte of
    // the record. Anchor SAVE_INN_REGISTRY_OFFSET to
    // SAVE_ROSTER_OFFSET + (SAVE_CHARACTER_RECORD_LEN - 1)
    // so the inn-registry offset derives from the roster
    // layout.
    assert_eq!(
        SAVE_INN_REGISTRY_OFFSET,
        SAVE_ROSTER_OFFSET + SAVE_CHARACTER_RECORD_LEN - 1,
    );
    assert_eq!(SAVE_INN_REGISTRY_OFFSET, 0x0021);
}

#[test]
fn first_playable_foot_transport_marker_anchors_to_foot_band_first() {
    // vehicles.md §2: the foot/avatar transport-family first
    // byte is the value the active player-marker is reset to
    // on dismount. constants.rs declared
    // FIRST_PLAYABLE_FOOT_TRANSPORT_MARKER = 28 as a bare
    // literal in parallel with predicates.rs's
    // TRANSPORT_MARKER_FOOT_FIRST = 0x1C. Anchor the
    // playable foot-marker to TRANSPORT_MARKER_FOOT_FIRST
    // so the foot-band start has one source of truth.
    assert_eq!(
        FIRST_PLAYABLE_FOOT_TRANSPORT_MARKER,
        TRANSPORT_MARKER_FOOT_FIRST,
    );
    assert_eq!(FIRST_PLAYABLE_FOOT_TRANSPORT_MARKER, 28);
}

#[test]
fn playable_vehicle_tile_bands_chain_from_vehicle_range_start() {
    // catalogs/tile-catalog.md §6: playable-vehicle tile
    // bands start at TILE_VEHICLE_FIRST (0xA0). Each major
    // vehicle (horse, frigate, skiff, carpet) occupies an
    // 8-tile band; the balloon *art* band starts 4 tiles past
    // the carpet. vehicles.md §11: "Balloon sprites are
    // catalog assets only" -- the band is a tile-catalog
    // anchor, not a transport family. Anchor the chain so
    // adding or resizing a vehicle shifts the later bands.
    assert_eq!(FIRST_PLAYABLE_HORSE_TILE, TILE_VEHICLE_FIRST);
    assert_eq!(FIRST_PLAYABLE_FRIGATE_TILE, FIRST_PLAYABLE_HORSE_TILE + 8);
    assert_eq!(FIRST_PLAYABLE_SKIFF_TILE, FIRST_PLAYABLE_FRIGATE_TILE + 8);
    assert_eq!(
        FIRST_PLAYABLE_MAGIC_CARPET_TILE,
        FIRST_PLAYABLE_SKIFF_TILE + 8
    );
    assert_eq!(
        FIRST_PLAYABLE_BALLOON_TILE,
        FIRST_PLAYABLE_MAGIC_CARPET_TILE + 4
    );
    assert_eq!(FIRST_PLAYABLE_HORSE_TILE, 160);
    assert_eq!(FIRST_PLAYABLE_BALLOON_TILE, 188);
}

#[test]
fn horse_object_and_transport_bands_chain_through_boarding_bias() {
    // vehicles.md §4: horse object bytes are 0x10..=0x11
    // (riderless) and 0x12..=0x13 (mounted). Boarding adds
    // 2 to the riderless object byte. Both bands are two
    // markers wide. Anchor *_LAST to FIRST + 1 and
    // HORSE_TRANSPORT_FIRST to HORSE_OBJECT_FIRST +
    // HORSE_BOARDING_BIAS so the horse band layout has one
    // source of truth.
    assert_eq!(HORSE_OBJECT_LAST, HORSE_OBJECT_FIRST + 1);
    assert_eq!(
        HORSE_TRANSPORT_FIRST,
        HORSE_OBJECT_FIRST + HORSE_BOARDING_BIAS
    );
    assert_eq!(HORSE_TRANSPORT_LAST, HORSE_TRANSPORT_FIRST + 1);
    assert_eq!(HORSE_BOARDING_BIAS, 2);
    assert_eq!(HORSE_OBJECT_FIRST, 0x10);
    assert_eq!(HORSE_TRANSPORT_LAST, 0x13);
}

#[test]
fn transport_marker_foot_band_is_two_frames_wide() {
    // vehicles.md §2: the on-foot family persists exactly 0x1C.
    // 0x1D is the second frame of the on-foot sprite pair, accepted
    // by the two "party is on foot" predicates as defensive breadth
    // but never written; 0x1E and 0x1F are outside the published
    // set entirely, so the band is two markers wide, not four.
    assert_eq!(
        TRANSPORT_MARKER_FOOT_LAST,
        TRANSPORT_MARKER_FOOT_FIRST + TRANSPORT_TWO_FRAME_WEST_BIAS,
    );
    assert_eq!(TRANSPORT_MARKER_FOOT_FIRST, 0x1C);
    assert_eq!(TRANSPORT_MARKER_FOOT_LAST, 0x1D);
    assert_eq!(transport_family(0x1E), None);
    assert_eq!(transport_family(0x1F), None);
}

#[test]
fn transport_marker_families_chain_through_facing_mask() {
    // vehicles.md §2: only the ship-hoisted, ship-furled and skiff
    // families carry full four-way facing in the low two bits
    // (TRANSPORT_FACING_MASK); those three bands tile contiguously
    // from 0x20. The magic carpet has TWO frames only - 0x14 east
    // and 0x15 west - so its band is anchored to
    // TRANSPORT_TWO_FRAME_WEST_BIAS instead, and 0x16/0x17 are
    // values the original engine cannot produce.
    assert_eq!(
        TRANSPORT_MARKER_MAGIC_CARPET_LAST,
        TRANSPORT_MARKER_MAGIC_CARPET_FIRST + TRANSPORT_TWO_FRAME_WEST_BIAS,
    );
    assert_eq!(
        TRANSPORT_MARKER_SHIP_HOISTED_LAST,
        TRANSPORT_MARKER_SHIP_HOISTED_FIRST + TRANSPORT_FACING_MASK,
    );
    assert_eq!(
        TRANSPORT_MARKER_SHIP_FURLED_FIRST,
        TRANSPORT_MARKER_SHIP_HOISTED_LAST + 1,
    );
    assert_eq!(
        TRANSPORT_MARKER_SHIP_FURLED_LAST,
        TRANSPORT_MARKER_SHIP_FURLED_FIRST + TRANSPORT_FACING_MASK,
    );
    assert_eq!(
        TRANSPORT_MARKER_SKIFF_FIRST,
        TRANSPORT_MARKER_SHIP_FURLED_LAST + 1,
    );
    assert_eq!(
        TRANSPORT_MARKER_SKIFF_LAST,
        TRANSPORT_MARKER_SKIFF_FIRST + TRANSPORT_FACING_MASK,
    );
    assert_eq!(TRANSPORT_MARKER_MAGIC_CARPET_LAST, 0x15);
    assert_eq!(transport_family(0x16), None);
    assert_eq!(transport_family(0x17), None);
    assert_eq!(TRANSPORT_MARKER_SHIP_HOISTED_LAST, 0x23);
    assert_eq!(TRANSPORT_MARKER_SKIFF_LAST, 0x2B);
}

#[test]
fn equip_slot_indices_chain_sequentially() {
    // inventory.md §3: per-character equipment slot indices
    // occupy 0..=5 in the published order (Helm, Armour,
    // Weapon, Off-hand, Ring, Amulet). Anchor each successor
    // to the chain so adding or reordering a slot only
    // happens in one place.
    assert_eq!(EQUIP_SLOT_ARMOUR, EQUIP_SLOT_HELM + 1);
    assert_eq!(EQUIP_SLOT_WEAPON, EQUIP_SLOT_ARMOUR + 1);
    assert_eq!(EQUIP_SLOT_OFFHAND, EQUIP_SLOT_WEAPON + 1);
    assert_eq!(EQUIP_SLOT_RING, EQUIP_SLOT_OFFHAND + 1);
    assert_eq!(EQUIP_SLOT_AMULET, EQUIP_SLOT_RING + 1);
    assert_eq!(EQUIP_SLOT_HELM, 0);
    assert_eq!(EQUIP_SLOT_AMULET, 5);
}

#[test]
fn reagent_indices_chain_sequentially() {
    // catalogs/spell-list.md §3: reagent enumeration order
    // packs the eight reagent indices into 0..=7 in sequence
    // (Sulfur Ash, Ginseng, Garlic, Spider Silk, Blood Moss,
    // Black Pearl, Nightshade, Mandrake). Anchor each
    // successor to the chain so adding or reordering a
    // reagent only happens in one place.
    assert_eq!(REAGENT_GINSENG, REAGENT_SULFUR_ASH + 1);
    assert_eq!(REAGENT_GARLIC, REAGENT_GINSENG + 1);
    assert_eq!(REAGENT_SPIDER_SILK, REAGENT_GARLIC + 1);
    assert_eq!(REAGENT_BLOOD_MOSS, REAGENT_SPIDER_SILK + 1);
    assert_eq!(REAGENT_BLACK_PEARL, REAGENT_BLOOD_MOSS + 1);
    assert_eq!(REAGENT_NIGHTSHADE, REAGENT_BLACK_PEARL + 1);
    assert_eq!(REAGENT_MANDRAKE, REAGENT_NIGHTSHADE + 1);
    assert_eq!(REAGENT_SULFUR_ASH, 0);
    assert_eq!(REAGENT_MANDRAKE, 7);
}

#[test]
