#[test]
fn reagent_recipe_masks_match_spec_table() {
    // catalogs/spell-list.md §3: per-reagent recipe-mask bits.
    // Bit 0x80 selects Sulfur Ash (index 0); each subsequent
    // reagent uses the next lower bit.
    assert_eq!(REAGENT_MASK_SULFUR_ASH, 0x80);
    assert_eq!(REAGENT_MASK_GINSENG, 0x40);
    assert_eq!(REAGENT_MASK_GARLIC, 0x20);
    assert_eq!(REAGENT_MASK_SPIDER_SILK, 0x10);
    assert_eq!(REAGENT_MASK_BLOOD_MOSS, 0x08);
    assert_eq!(REAGENT_MASK_BLACK_PEARL, 0x04);
    assert_eq!(REAGENT_MASK_NIGHTSHADE, 0x02);
    assert_eq!(REAGENT_MASK_MANDRAKE, 0x01);
    // The packed table at REAGENT_MASKS lines up with the
    // index-keyed constants (REAGENT_*).
    assert_eq!(REAGENT_MASKS[REAGENT_SULFUR_ASH], REAGENT_MASK_SULFUR_ASH);
    assert_eq!(REAGENT_MASKS[REAGENT_GINSENG], REAGENT_MASK_GINSENG);
    assert_eq!(REAGENT_MASKS[REAGENT_GARLIC], REAGENT_MASK_GARLIC);
    assert_eq!(REAGENT_MASKS[REAGENT_SPIDER_SILK], REAGENT_MASK_SPIDER_SILK);
    assert_eq!(REAGENT_MASKS[REAGENT_BLOOD_MOSS], REAGENT_MASK_BLOOD_MOSS);
    assert_eq!(REAGENT_MASKS[REAGENT_BLACK_PEARL], REAGENT_MASK_BLACK_PEARL);
    assert_eq!(REAGENT_MASKS[REAGENT_NIGHTSHADE], REAGENT_MASK_NIGHTSHADE);
    assert_eq!(REAGENT_MASKS[REAGENT_MANDRAKE], REAGENT_MASK_MANDRAKE);
    // The eight bits together cover the full byte.
    let union: u8 = REAGENT_MASKS.iter().fold(0, |acc, b| acc | b);
    assert_eq!(union, 0xFF);
}

#[test]
fn spell_scene_bit_and_mp_cost_route_through_named_constants() {
    // catalogs/spell-list.md §4: scene-byte classifier and §10
    // spell-MP-cost formula both rely on already-promoted named
    // constants.
    assert_eq!(SPELLS_PER_CIRCLE, 6);
    // Scene-byte classifier routes through the SCENE_* ranges.
    assert_eq!(
        spell_scene_bit_for_scene_byte(SCENE_OVERWORLD),
        SPELL_SCENE_BIT_OVERWORLD
    );
    assert_eq!(
        spell_scene_bit_for_scene_byte(SCENE_TOWN_FAMILY_FIRST),
        SPELL_SCENE_BIT_INDOOR,
    );
    assert_eq!(
        spell_scene_bit_for_scene_byte(SCENE_TOWN_FAMILY_LAST),
        SPELL_SCENE_BIT_INDOOR,
    );
    assert_eq!(
        spell_scene_bit_for_scene_byte(SCENE_DUNGEON_FAMILY_FIRST),
        SPELL_SCENE_BIT_DUNGEON,
    );
    assert_eq!(
        spell_scene_bit_for_scene_byte(SCENE_DUNGEON_FAMILY_LAST),
        SPELL_SCENE_BIT_DUNGEON,
    );
    assert_eq!(
        spell_scene_bit_for_scene_byte(SCENE_COMBAT_TEMPORARY),
        SPELL_SCENE_BIT_COMBAT,
    );
    // MP cost = (spell_index / SPELLS_PER_CIRCLE) + 1 — circle 1 = 1 MP,
    // circle 8 = 8 MP.
    assert_eq!(spell_mp_cost(0), Some(1));
    assert_eq!(spell_mp_cost(SPELLS_PER_CIRCLE - 1), Some(1));
    assert_eq!(spell_mp_cost(SPELLS_PER_CIRCLE), Some(2));
    assert_eq!(spell_mp_cost(SPELL_COUNT - 1), Some(8));
    assert_eq!(spell_mp_cost(SPELL_COUNT), None);
    // Zero-based circle = spell_index / SPELLS_PER_CIRCLE.
    assert_eq!(spell_circle_index(0), Some(0));
    assert_eq!(spell_circle_index(SPELLS_PER_CIRCLE), Some(1));
    assert_eq!(spell_circle_index(SPELL_COUNT - 1), Some(7));
    assert_eq!(spell_circle_index(SPELL_COUNT), None);
}

#[test]
fn ship_transport_heading_routes_through_named_facing_mask() {
    // vehicles.md §6: the ship transport marker's low two bits
    // decode heading as north(0)/east(1)/south(2)/west(3).
    // ship_transport_heading_index must route through
    // TRANSPORT_FACING_MASK so the helper agrees with
    // transport_facing_index on every ship marker.
    for marker in TRANSPORT_MARKER_SHIP_HOISTED_FIRST..=TRANSPORT_MARKER_SHIP_FURLED_LAST {
        let direct = ship_transport_heading_index(marker);
        let generic = transport_facing_index(marker);
        assert_eq!(direct, generic, "marker 0x{marker:02X}");
        assert_eq!(direct, Some(marker & TRANSPORT_FACING_MASK));
    }
    // Non-ship transport markers return None from the ship-specific
    // helper even though the shared facing decoder accepts them.
    assert_eq!(
        ship_transport_heading_index(TRANSPORT_MARKER_FOOT_DEFAULT),
        None
    );
    assert_eq!(
        ship_transport_heading_index(TRANSPORT_MARKER_SKIFF_FIRST),
        None
    );
}

