#[test]
fn prng_state_advance_constants_match_spec() {
    // prng.md §2: the state advance adds 0x9248, rotates right
    // by three bits, XORs with 0x9248 again, and adds 0x0011.
    // The non-negative mask is 0x7FFF (low 15 bits) and is
    // applied before the modulo reduction.
    assert_eq!(PRNG_STATE_ADD, 0x9248);
    assert_eq!(PRNG_STATE_ROTATE_BITS, 3);
    assert_eq!(PRNG_STATE_FINAL_BIAS, 0x0011);
    assert_eq!(PRNG_NON_NEGATIVE_MASK, 0x7FFF);
    // u5_prng_advance_state matches the recurrence built from the
    // named constants.
    let state: u16 = 0;
    let expected = (state
        .wrapping_add(PRNG_STATE_ADD)
        .rotate_right(PRNG_STATE_ROTATE_BITS)
        ^ PRNG_STATE_ADD)
        .wrapping_add(PRNG_STATE_FINAL_BIAS);
    assert_eq!(u5_prng_advance_state(state), expected);
}

#[test]
fn tlk_dictionary_token_range_matches_spec() {
    // formats/tlk.md §9,§10: dialogue dictionary tokens are 0x01..=0x80,
    // biased by one onto the 128-entry common-word table. The band is NOT
    // "high bit clear" - its last member 0x80 has bit seven set, and §9's
    // dispatch table marks 0x80 "not a control code".
    //
    // 128 entries need 128 token values; 0x01..=0x7F is 127, so under the
    // withdrawn bound the last entry was unreachable by any token. The
    // shipped corpus uses 0x80 mid-payload thirteen times, always between
    // ordinary text, and entry 127 is "work" - e.g. TOWNE.TLK "I <0x80>
    // hard-" and CASTLE.TLK "Mystic arms <0x80> near".
    assert_eq!(TLK_DICTIONARY_TOKEN_FIRST, 0x01);
    assert_eq!(TLK_DICTIONARY_TOKEN_LAST, 0x80);
    // NUL is not a token; 0x80 IS one; 0x81 begins the control band.
    assert_eq!(tlk_dictionary_index(0), None);
    assert_eq!(tlk_dictionary_index(0x80), Some(127));
    assert_eq!(tlk_dictionary_index(0x81), None);
    // Boundary tokens round-trip through the index helper.
    assert_eq!(tlk_dictionary_index(TLK_DICTIONARY_TOKEN_FIRST), Some(0),);
    assert_eq!(
        tlk_dictionary_index(TLK_DICTIONARY_TOKEN_LAST),
        Some((TLK_DICTIONARY_TOKEN_LAST - TLK_DICTIONARY_TOKEN_FIRST) as usize),
    );
    // The corrected band covers the table EXACTLY: 0x01..=0x80 is 128
    // token values for 128 entries, with no entry unreachable and no
    // token spare. This assertion previously read `ENTRIES - 1`, which is
    // the off-by-one stated as arithmetic - the test was not merely
    // agreeing with the wrong constant, it was independently asserting
    // that one dictionary entry had no token, which is not a thing a
    // pointer table does.
    assert_eq!(
        (TLK_DICTIONARY_TOKEN_LAST as usize) - (TLK_DICTIONARY_TOKEN_FIRST as usize) + 1,
        COMMON_WORD_DICTIONARY_ENTRIES,
    );
}

#[test]
fn tlk_printable_and_control_byte_ranges_match_spec() {
    // conversation.md §7: high-bit-set bytes in 0xA0..=0xFD are
    // printable text; the control band is published as "0x81..0x9F
    // with the exception of the GOTO range", and §7.7 fixes the GOTO
    // range at 0x91..=0x9F, so the control codes proper are
    // 0x81..=0x90.
    //
    // The 0x9D this test used to assert was the wrong end of that
    // subtraction -- it left 0x91..=0x9D classified as control codes.
    assert_eq!(TLK_PRINTABLE_TEXT_FIRST, 0xA0);
    assert_eq!(TLK_PRINTABLE_TEXT_LAST, 0xFD);
    assert_eq!(TLK_CONTROL_CODE_FIRST, 0x81);
    assert_eq!(TLK_CONTROL_CODE_LAST, 0x90);
    // Adjacencies, asserted as consequences of independent literals
    // rather than as the definitions they used to be.
    assert_eq!(TLK_CONTROL_CODE_LAST + 1, TLK_LABEL_FIRST);
    assert_eq!(TLK_LABEL_LAST + 1, TLK_PRINTABLE_TEXT_FIRST);
}

#[test]
fn player_sail_wait_ticks_route_through_named_constants() {
    // weather.md §5: hoisted-sail wait-tick release table.
    assert_eq!(PLAYER_SAIL_WAIT_TICKS_PERPENDICULAR, 0);
    assert_eq!(PLAYER_SAIL_WAIT_TICKS_WITH_WIND, 1);
    assert_eq!(PLAYER_SAIL_WAIT_TICKS_INTO_WIND, 2);
    // North wind + south-facing sail: "with the wind" (one wait).
    assert_eq!(
        WindState::North.player_sail_wait_ticks(Direction::South),
        Some(PLAYER_SAIL_WAIT_TICKS_WITH_WIND),
    );
    // North wind + north-facing sail: "into the wind" (two waits).
    assert_eq!(
        WindState::North.player_sail_wait_ticks(Direction::North),
        Some(PLAYER_SAIL_WAIT_TICKS_INTO_WIND),
    );
    // North wind + east-facing sail: perpendicular (immediate).
    assert_eq!(
        WindState::North.player_sail_wait_ticks(Direction::East),
        Some(PLAYER_SAIL_WAIT_TICKS_PERPENDICULAR),
    );
    // sailing_wait_pass_minutes routes through the named indoor
    // and outdoor cadences per §5.
    assert_eq!(
        WindState::sailing_wait_pass_minutes(false),
        MINUTES_PER_OUTDOOR_TURN,
    );
    assert_eq!(
        WindState::sailing_wait_pass_minutes(true),
        MINUTES_PER_INDOOR_TURN,
    );
}

#[test]
fn active_ship_cadence_ratios_match_spec_table() {
    // weather.md §7: per-frame active-ship cadence caps. Each pair
    // is (numerator, denominator).
    assert_eq!(ACTIVE_SHIP_CADENCE_EVERY_TURN, (1, 1));
    assert_eq!(ACTIVE_SHIP_CADENCE_INTO_WIND, (2, 3));
    assert_eq!(ACTIVE_SHIP_CADENCE_WITH_WIND, (3, 4));
    // North wind + north-facing frame is "into wind" (2 of 3).
    assert_eq!(
        WindState::North.active_ship_cadence(Direction::North),
        Some(ACTIVE_SHIP_CADENCE_INTO_WIND),
    );
    // North wind + south-facing frame is "with wind" (3 of 4).
    assert_eq!(
        WindState::North.active_ship_cadence(Direction::South),
        Some(ACTIVE_SHIP_CADENCE_WITH_WIND),
    );
    // North wind + east-facing frame is perpendicular = every turn.
    assert_eq!(
        WindState::North.active_ship_cadence(Direction::East),
        Some(ACTIVE_SHIP_CADENCE_EVERY_TURN),
    );
    // Calm suppresses cadence entirely.
    assert_eq!(WindState::Calm.active_ship_cadence(Direction::North), None,);
}

#[test]
fn ship_broadside_damage_roll_routes_through_named_min_max() {
    // vehicles.md §7: a successful broadside subtracts a random
    // 1..20 amount from the target object's active-object byte +5.
    // The damage-roll helper must derive its result through the
    // promoted SHIP_BROADSIDE_DAMAGE_MIN / SHIP_BROADSIDE_DAMAGE_MAX
    // constants rather than bare literals.
    assert_eq!(SHIP_BROADSIDE_DAMAGE_MIN, 1);
    assert_eq!(SHIP_BROADSIDE_DAMAGE_MAX, 20);
    // The min is the floor and the helper's modulus is the max; the
    // resulting roll therefore lies in [MIN, MIN + MAX - 1].
    let highest = SHIP_BROADSIDE_DAMAGE_MIN + SHIP_BROADSIDE_DAMAGE_MAX - 1;
    assert_eq!(highest, 20);
}

#[test]
fn transport_marker_ranges_match_spec_table() {
    // vehicles.md §2: the ship and skiff families carry full
    // four-way facing in their low two bits; the horse, carpet and
    // on-foot families are two frames wide.
    assert_eq!(TRANSPORT_FACING_MASK, 0b0000_0011);
    assert_eq!(TRANSPORT_TWO_FRAME_WEST_BIAS, 1);
    assert_eq!(TRANSPORT_MARKER_MAGIC_CARPET_FIRST, 0x14);
    assert_eq!(TRANSPORT_MARKER_MAGIC_CARPET_LAST, 0x15);
    assert_eq!(TRANSPORT_MARKER_SHIP_HOISTED_FIRST, 0x20);
    assert_eq!(TRANSPORT_MARKER_SHIP_HOISTED_LAST, 0x23);
    assert_eq!(TRANSPORT_MARKER_SHIP_FURLED_FIRST, 0x24);
    assert_eq!(TRANSPORT_MARKER_SHIP_FURLED_LAST, 0x27);
    assert_eq!(TRANSPORT_MARKER_SKIFF_FIRST, 0x28);
    assert_eq!(TRANSPORT_MARKER_SKIFF_LAST, 0x2B);
    // Every range is exactly four markers wide.
    for (first, last) in [
        (HORSE_TRANSPORT_FIRST, HORSE_TRANSPORT_LAST),
        (
            TRANSPORT_MARKER_MAGIC_CARPET_FIRST,
            TRANSPORT_MARKER_MAGIC_CARPET_LAST,
        ),
        (TRANSPORT_MARKER_FOOT_FIRST, TRANSPORT_MARKER_FOOT_LAST),
        (
            TRANSPORT_MARKER_SHIP_HOISTED_FIRST,
            TRANSPORT_MARKER_SHIP_HOISTED_LAST,
        ),
        (
            TRANSPORT_MARKER_SHIP_FURLED_FIRST,
            TRANSPORT_MARKER_SHIP_FURLED_LAST,
        ),
        (TRANSPORT_MARKER_SKIFF_FIRST, TRANSPORT_MARKER_SKIFF_LAST),
    ] {
        // Mounted horse (0x12..=0x13), magic carpet (0x14..=0x15)
        // and foot (0x1C..=0x1D) are two markers wide; the ship and
        // skiff families are four. Every shape needs its low-bit
        // facing nibble to round-trip through the mask.
        assert!(last >= first);
        for marker in first..=last {
            assert_eq!(
                transport_facing_index(marker),
                Some(marker & TRANSPORT_FACING_MASK),
            );
        }
    }
}

#[test]
fn tile_passability_bit_shift_and_mask_align_with_spec() {
    // movement.md §4: the base terrain bitset packs eight tile-id
    // bits per byte; byte index is `tile >> 3` and within-byte bit
    // is selected by `tile & 7`, MSB-first.
    assert_eq!(TILE_PASSABILITY_BIT_INDEX_SHIFT, 3);
    assert_eq!(TILE_PASSABILITY_BIT_INDEX_MASK, 7);
    // `1 << SHIFT` is the bit-width per byte and equals
    // `MASK + 1` (the number of distinct within-byte positions).
    assert_eq!(
        1u8 << TILE_PASSABILITY_BIT_INDEX_SHIFT,
        TILE_PASSABILITY_BIT_INDEX_MASK + 1
    );
    // The 32-byte bitset times eight bits per byte covers every
    // tile id in 0..=255.
    assert_eq!(
        TILE_PASSABILITY_LEN * (1usize << TILE_PASSABILITY_BIT_INDEX_SHIFT),
        256,
    );
}

fn movement_range_table(ranges: &[(u8, u8)]) -> [bool; 256] {
    let mut table = [false; 256];
    for &(first, last) in ranges {
        for tile in first..=last {
            table[tile as usize] = true;
        }
    }
    table
}

