#[test]
fn dungeon_render_cell_byte_strips_visit_bit_below_wall_band() {
    // dungeon-mode.md §6.1: renderer-facing cell reads strip
    // bit 0x08 from cell bytes below 0x90 before class
    // interpretation; classes 0x9? and higher keep the bit.
    // Below the band: visit marker is cleared.
    assert_eq!(dungeon_render_cell_byte(0x00), 0x00);
    assert_eq!(dungeon_render_cell_byte(0x08), 0x00);
    assert_eq!(dungeon_render_cell_byte(0x68), 0x60);
    assert_eq!(dungeon_render_cell_byte(0x8B), 0x83);
    // At and above the wall/door band: bit is preserved.
    assert_eq!(dungeon_render_cell_byte(0x90), 0x90);
    assert_eq!(dungeon_render_cell_byte(0x98), 0x98);
    assert_eq!(dungeon_render_cell_byte(0xFF), 0xFF);
    assert_eq!(
        dungeon_render_cell_byte(DUNGEON_WALL_DOOR_BAND_FIRST),
        DUNGEON_WALL_DOOR_BAND_FIRST
    );
}

#[test]
fn dungeon_facing_side_deltas_match_spec_rotations() {
    // dungeon-mode.md §6: side-wall mirroring reads cells to the
    // left and right of the forward path. Left rotates the
    // forward delta 90 CCW; right rotates it 90 CW.
    // Facing North: forward (0,-1), left (-1,0), right (1,0).
    assert_eq!(
        dungeon_facing_left_delta(DUNGEON_FACING_NORTH),
        Some((-1, 0))
    );
    assert_eq!(
        dungeon_facing_right_delta(DUNGEON_FACING_NORTH),
        Some((1, 0))
    );
    // Facing East: forward (1,0), left (0,-1), right (0,1).
    assert_eq!(
        dungeon_facing_left_delta(DUNGEON_FACING_EAST),
        Some((0, -1))
    );
    assert_eq!(
        dungeon_facing_right_delta(DUNGEON_FACING_EAST),
        Some((0, 1))
    );
    // Facing South: forward (0,1), left (1,0), right (-1,0).
    assert_eq!(
        dungeon_facing_left_delta(DUNGEON_FACING_SOUTH),
        Some((1, 0))
    );
    assert_eq!(
        dungeon_facing_right_delta(DUNGEON_FACING_SOUTH),
        Some((-1, 0))
    );
    // Facing West: forward (-1,0), left (0,1), right (0,-1).
    assert_eq!(dungeon_facing_left_delta(DUNGEON_FACING_WEST), Some((0, 1)));
    assert_eq!(
        dungeon_facing_right_delta(DUNGEON_FACING_WEST),
        Some((0, -1))
    );
    // Invalid facing returns None.
    assert_eq!(dungeon_facing_left_delta(4), None);
    assert_eq!(dungeon_facing_right_delta(255), None);
    // Left + right = (0, 0) for every cardinal facing.
    for facing in 0..=3u8 {
        let (lx, ly) = dungeon_facing_left_delta(facing).unwrap();
        let (rx, ry) = dungeon_facing_right_delta(facing).unwrap();
        assert_eq!((lx + rx, ly + ry), (0, 0));
    }
}

#[test]
fn sky_strip_marker_band_offsets_match_spec() {
    // moons.md §2: per-marker visible-hour bands and cell-position
    // offsets. Each marker's cell is `offset - hour` when the
    // current hour is inside its band.
    assert_eq!(SKY_STRIP_FIXED_HOUR_BAND_FIRST, 6);
    assert_eq!(SKY_STRIP_FIXED_HOUR_BAND_LAST, 17);
    assert_eq!(SKY_STRIP_FIXED_HOUR_OFFSET, 17);
    assert_eq!(SKY_STRIP_TRAMMEL_MORNING_OFFSET, 8);
    assert_eq!(SKY_STRIP_TRAMMEL_NIGHT_OFFSET, 32);
    assert_eq!(SKY_STRIP_FELUCCA_MORNING_OFFSET, 2);
    assert_eq!(SKY_STRIP_FELUCCA_AFTERNOON_OFFSET, 26);
    // The renderer's cell-position computation lines up with the
    // promoted offsets for in-band hours and returns None outside.
    assert_eq!(
        sky_strip_marker_position(12, SkyStripMarker::FixedHour),
        Some(SKY_STRIP_FIXED_HOUR_OFFSET - 12),
    );
    assert_eq!(
        sky_strip_marker_position(0, SkyStripMarker::FixedHour),
        None
    );
    assert_eq!(
        sky_strip_marker_position(0, SkyStripMarker::Trammel),
        Some(SKY_STRIP_TRAMMEL_MORNING_OFFSET),
    );
    assert_eq!(
        sky_strip_marker_position(22, SkyStripMarker::Trammel),
        Some(SKY_STRIP_TRAMMEL_NIGHT_OFFSET - 22),
    );
}

