#[test]
fn resurrection_penalty_percent_divisor_matches_spec() {
    // karma.md §5 / magic.md §8: the resurrection XP scaler
    // multiplies by the moral-standing selector and divides by
    // 100; promote the divisor so both helpers share one named
    // source of truth.
    assert_eq!(RESURRECTION_PENALTY_PERCENT_DIVISOR, 100);
    assert_eq!(RESURRECTION_PENALTY_SKIP_THRESHOLD, 98);
    // Skip threshold: a 98+ selector leaves XP unchanged.
    assert_eq!(
        resurrection_scaled_xp(RESURRECTION_PENALTY_SKIP_THRESHOLD, 1234),
        1234,
    );
    assert_eq!(resurrection_scaled_xp(99, 1234), 1234);
    // Below the threshold the scale runs: standing 50 yields half.
    assert_eq!(resurrection_scaled_xp(50, 200), 100);
    // resurrection_adjusted_experience uses the same constants.
    assert_eq!(
        resurrection_adjusted_experience(1234, RESURRECTION_PENALTY_SKIP_THRESHOLD),
        1234,
    );
}

#[test]
fn karma_action_signed_deltas_route_through_named_constants() {
    // karma.md §4 confirmed scalar mutators. Route each non-shrine
    // delta through its named promoted constant so the table here
    // can be audited against the spec without re-checking the
    // signed_delta arithmetic for bare literals.
    assert_eq!(KARMA_HELPED_NPC_THANK_YOU_GAIN, 2);
    assert_eq!(KARMA_TOLL_MILESTONE_GAIN, 1);
    assert_eq!(KARMA_TOLL_MILESTONE_ZERO_GOLD_BONUS, 2);
    assert_eq!(
        KarmaAction::TownChestOpened.signed_delta(),
        -(TOWN_CHEST_OPEN_KARMA_DEBIT as i16),
    );
    assert_eq!(
        KarmaAction::CropOrTableFoodTaken.signed_delta(),
        -(KARMA_CROP_OR_TABLE_FOOD_DEBIT as i16),
    );
    assert_eq!(
        KarmaAction::TownCannonHit.signed_delta(),
        -(TOWN_CANNON_HIT_KARMA_DEBIT as i16),
    );
    assert_eq!(
        KarmaAction::HelpedNpcThankYou.signed_delta(),
        KARMA_HELPED_NPC_THANK_YOU_GAIN as i16,
    );
    assert_eq!(
        KarmaAction::TollMilestone {
            left_party_with_zero_gold: false
        }
        .signed_delta(),
        KARMA_TOLL_MILESTONE_GAIN as i16,
    );
    assert_eq!(
        KarmaAction::TollMilestone {
            left_party_with_zero_gold: true
        }
        .signed_delta(),
        (KARMA_TOLL_MILESTONE_GAIN + KARMA_TOLL_MILESTONE_ZERO_GOLD_BONUS) as i16,
    );
    // Codex turn-in: base +3, Humility doubles to +6.
    assert_eq!(
        KarmaAction::CodexShrineTurnIn { humility: false }.signed_delta(),
        ShrineVirtue::SHRINE_CODEX_TURN_IN_MORAL_INCREASE as i16,
    );
    assert_eq!(
        KarmaAction::CodexShrineTurnIn { humility: true }.signed_delta(),
        (ShrineVirtue::SHRINE_CODEX_TURN_IN_MORAL_INCREASE as i16) * 2,
    );
}

#[test]
fn daylight_sentinel_min_anchors_to_full_daylight() {
    // time.md §6 / lighting.md §3: values strictly above
    // FULL_DAYLIGHT (= 50) are the "skip recompute" sentinel
    // band; DAYLIGHT_SENTINEL_MIN names the first byte in that
    // band and must equal FULL_DAYLIGHT + 1.
    assert_eq!(FULL_DAYLIGHT, 50);
    assert_eq!(FULL_DARKNESS, 2);
    assert_eq!(DAYLIGHT_SENTINEL_MIN, FULL_DAYLIGHT + 1);
    assert_eq!(DAYLIGHT_SENTINEL_MIN, 51);
    // ambient_is_sentinel must agree at the boundary.
    assert!(!ambient_is_sentinel(FULL_DAYLIGHT));
    assert!(ambient_is_sentinel(DAYLIGHT_SENTINEL_MIN));
}

#[test]
fn cleanup_increment_recompute_matches_spec() {
    // time.md §3: the per-turn cleanup routine takes one word
    // argument. Argument 0 is the "recompute, do not advance"
    // mode-zero call used at scene transitions; arguments 1 and 2
    // are the town/dungeon and overworld minute cadences.
    assert_eq!(CLEANUP_INCREMENT_RECOMPUTE, 0);
    assert_eq!(MINUTES_PER_INDOOR_TURN, 1);
    assert_eq!(MINUTES_PER_OUTDOOR_TURN, 2);
    assert_ne!(CLEANUP_INCREMENT_RECOMPUTE, MINUTES_PER_INDOOR_TURN);
    assert_ne!(CLEANUP_INCREMENT_RECOMPUTE, MINUTES_PER_OUTDOOR_TURN);
}

#[test]
fn level_from_experience_scaler_matches_spec() {
    // u4-transfer.md §7 / magic.md §8: level starts at 1; the
    // experience-to-level scaler divides by 100, then halves the
    // quotient repeatedly to step the level up while the quotient
    // remains nonzero.
    assert_eq!(LEVEL_FROM_EXPERIENCE_BASE_DIVISOR, 100);
    assert_eq!(LEVEL_FROM_EXPERIENCE_HALVING_STEP, 2);
    // Boundary cases from the spec:
    assert_eq!(recompute_level_from_experience(0), 1);
    assert_eq!(recompute_level_from_experience(99), 1);
    assert_eq!(recompute_level_from_experience(100), 2);
    assert_eq!(recompute_level_from_experience(199), 2);
    assert_eq!(recompute_level_from_experience(200), 3);
    assert_eq!(recompute_level_from_experience(399), 3);
    assert_eq!(recompute_level_from_experience(400), 4);
}

#[test]
fn u4_transfer_attribute_translator_bands_match_spec() {
    // u4-transfer.md §7: three-band primary-attribute translator.
    // Band edges: low 0..=9, mid 10..=29, high 30+.
    assert_eq!(U4_TRANSFER_ATTRIBUTE_LOW_BAND_END, 10);
    assert_eq!(U4_TRANSFER_ATTRIBUTE_MID_BAND_END, 30);
    assert_eq!(U4_TRANSFER_ATTRIBUTE_LOW_BAND_BIAS, 9);
    assert_eq!(U4_TRANSFER_ATTRIBUTE_MID_BAND_DIVISOR, 2);
    assert_eq!(U4_TRANSFER_ATTRIBUTE_MID_BAND_BIAS_OUT, 10);
    assert_eq!(U4_TRANSFER_ATTRIBUTE_HIGH_BAND_BIAS, 30);
    assert_eq!(U4_TRANSFER_ATTRIBUTE_HIGH_BAND_DIVISOR, 4);
    assert_eq!(U4_TRANSFER_ATTRIBUTE_HIGH_BAND_BIAS_OUT, 20);
    assert_eq!(U4_TRANSFER_STRENGTH_FLOOR, 20);
    assert_eq!(U4_TRANSFER_EXPERIENCE_DIVISOR, 10);
    // Sample band boundaries: 0 -> 0, 9 -> 9, 10 -> 10
    // (since (10-9)/2 = 0, +10 = 10), 29 -> 20 ((29-9)/2 = 10, +10 = 20),
    // 30 -> 20 ((30-30)/4 = 0, +20 = 20), 99 -> 37
    // ((99-30)/4 = 17, +20 = 37).
    assert_eq!(u4_transfer_attribute_to_u5(0), 0);
    assert_eq!(u4_transfer_attribute_to_u5(9), 9);
    assert_eq!(u4_transfer_attribute_to_u5(10), 10);
    assert_eq!(u4_transfer_attribute_to_u5(29), 20);
    assert_eq!(u4_transfer_attribute_to_u5(30), 20);
    assert_eq!(u4_transfer_attribute_to_u5(99), 37);
    // Strength is floored to 20; Dex/Int are not floored.
    assert_eq!(u4_transfer_strength_to_u5(0), U4_TRANSFER_STRENGTH_FLOOR);
    assert_eq!(u4_transfer_strength_to_u5(99), 37);
    // Experience divisor: 999 / 10 = 99.
    assert_eq!(u4_transfer_experience_to_u5(999), 99);
}

#[test]
fn save_flow_underworld_write_uses_entry_required_disk() {
    // save-load.md §5.2 step 5: the one save-time UNDER.OOL
    // write is skipped only when the entry required-disk state is
    // already canonical Britannia index 1.
    assert!(!save_flow_writes_underworld_mirror(RequiredDisk::Britannia));
    assert!(save_flow_writes_underworld_mirror(RequiredDisk::Program));
    assert!(save_flow_writes_underworld_mirror(
        RequiredDisk::UltimaVSave
    ));
    assert!(save_flow_writes_underworld_mirror(
        RequiredDisk::UltimaIvPlayer
    ));
}

#[test]
fn terrain_combat_early_spawn_threshold_matches_spec() {
    // combat.md §5: early-spawn band is spawn indexes below
    // `count / 4 + 1`. Each early spawn rolls a one-in-nine
    // replacement check; later spawn indexes never roll.
    assert_eq!(TERRAIN_COMBAT_REPLACEMENT_EARLY_SPAWN_DIVISOR, 4);
    assert_eq!(TERRAIN_COMBAT_REPLACEMENT_EARLY_SPAWN_BIAS, 1);
    // A count of 8 admits early spawn indexes 0..=2 (threshold 3).
    assert_eq!(terrain_combat_replacement_threshold(8), 3);
    // A count of 1 admits only spawn index 0 (threshold 1).
    assert_eq!(terrain_combat_replacement_threshold(1), 1);
    // A count of 0 still admits the bias band (threshold 1).
    assert_eq!(terrain_combat_replacement_threshold(0), 1);
}

#[test]
fn combat_spawn_count_exact_sentinels_match_spec() {
    // combat.md §5: the per-arena spawn-count byte values 1, 8,
    // and 16 are exact counts used unchanged; every other nonzero
    // value is treated as a maximum and rolled uniformly in
    // [1, max].
    assert_eq!(COMBAT_SPAWN_COUNT_EXACT_VALUES, [1, 8, 16]);
    for &exact in &COMBAT_SPAWN_COUNT_EXACT_VALUES {
        assert_eq!(resolve_combat_spawn_count(exact, 99, None), exact);
        assert_eq!(resolve_combat_spawn_count(exact, 99, Some(42)), exact);
    }
    // A non-exact maximum still rolls in [1, max] and is clamped
    // by COMBAT_SPAWN_COUNT_CAP.
    assert!(resolve_combat_spawn_count(5, 0, None) >= 1);
    assert!(resolve_combat_spawn_count(5, 4, None) <= 5);
}

#[test]
fn text_color_packed_byte_nibbles_match_spec() {
    // text-output.md §3: the active window's colour attribute
    // carries the foreground palette index in its low nibble and
    // the background palette index in its high nibble. Both
    // nibbles are four bits wide.
    assert_eq!(TEXT_COLOR_FOREGROUND_MASK, 0x0F);
    assert_eq!(TEXT_COLOR_BACKGROUND_SHIFT, 4);
    // Boot defaults: fg 15 (bright white), bg 0 (black) — packed
    // through the named shift produces the canonical 0x0F byte
    // and round-trips through the named accessors.
    let packed = text_window_default_color_byte();
    assert_eq!(packed, 0x0F);
    assert_eq!(
        text_color_foreground(packed),
        TEXT_WINDOW_DEFAULT_FOREGROUND
    );
    assert_eq!(
        text_color_background(packed),
        TEXT_WINDOW_DEFAULT_BACKGROUND
    );
    // Mixed sample: fg 3 (cyan) on bg 7 (light grey) packs to 0x73.
    assert_eq!(text_color_foreground(0x73), 3);
    assert_eq!(text_color_background(0x73), 7);
}

#[test]
fn mmix_quantity_prompt_width_matches_spec() {
    // magic.md §6: M-Mix step 4 reads a two-digit unsigned
    // quantity. The maximum accepted value is 99 and matches the
    // shared SPELL_CHARGE_CAP.
    assert_eq!(MMIX_QUANTITY_PROMPT_DIGITS, 2);
    assert_eq!(MMIX_QUANTITY_PROMPT_MAX, 99);
    assert_eq!(MMIX_QUANTITY_PROMPT_MAX, SPELL_CHARGE_CAP);
    // The maximum equals 10^digits - 1.
    let mut ten_pow_digits: u32 = 1;
    for _ in 0..MMIX_QUANTITY_PROMPT_DIGITS {
        ten_pow_digits *= 10;
    }
    assert_eq!(ten_pow_digits as u8 - 1, MMIX_QUANTITY_PROMPT_MAX);
}

#[test]
fn title_surface_dimensions_match_spec() {
    // intro.md §3: title-screen 320x200 pixel coordinate system
    // with the origin at the upper-left corner.
    assert_eq!(TITLE_SURFACE_WIDTH, 320);
    assert_eq!(TITLE_SURFACE_HEIGHT, 200);
    // Every published title placement must stay inside the surface.
    for placement in TITLE_BIT_INITIAL_PLACEMENTS
        .iter()
        .chain(TITLE_BIT_REMAINING_PLACEMENTS.iter())
    {
        assert!(
            placement.top_left_x + placement.width <= TITLE_SURFACE_WIDTH,
            "slot {} X exceeds surface",
            placement.slot,
        );
        assert!(
            placement.top_left_y + placement.height <= TITLE_SURFACE_HEIGHT,
            "slot {} Y exceeds surface",
            placement.slot,
        );
    }
    // The title-tick frame rectangle also fits inside the surface.
    assert!(TITLE_TICK_FRAME_X + TITLE_TICK_FRAME_WIDTH <= TITLE_SURFACE_WIDTH);
    assert!(TITLE_TICK_FRAME_Y + TITLE_TICK_FRAME_HEIGHT <= TITLE_SURFACE_HEIGHT);
}

#[test]
fn tile_pixel_packing_density_matches_spec() {
    // formats/tiles.md §3: the .16 files store two four-bit
    // pixels per byte (chunky packed, high nibble first).
    // formats/tiles.md §4: the .4 files store four two-bit pixels
    // per byte (packed, most-significant bits first).
    assert_eq!(EGA_PIXELS_PER_BYTE, 2);
    assert_eq!(CGA_PIXELS_PER_BYTE, 4);
    // Derived tile cost: a 16x16 tile becomes 128 EGA bytes or
    // 64 CGA bytes; CGA is exactly half the EGA cost.
    assert_eq!(EGA_TILE_BYTES, 128);
    assert_eq!(CGA_TILE_BYTES, 64);
    assert_eq!(EGA_TILE_BYTES, CGA_TILE_BYTES * 2);
}

