#[test]
fn dungeon_cell_nibble_mask_and_shift_match_spec() {
    // formats/dungeon-dat.md §3: each cell byte's upper nibble
    // selects the broad dispatch class, and the lower nibble
    // carries the class-specific attribute/subtype/sentinel.
    assert_eq!(DUNGEON_CELL_LOW_NIBBLE_MASK, 0x0F);
    assert_eq!(DUNGEON_CELL_HIGH_NIBBLE_SHIFT, 4);
    // 0x5A is a fountain (class 0x5) with low nibble 0xA — the
    // subtype falls outside the named 0..=2 effects and collapses
    // to the BadTaste catch-all.
    let cell = 0x5A;
    assert_eq!(cell >> DUNGEON_CELL_HIGH_NIBBLE_SHIFT, 0x5);
    assert_eq!(cell & DUNGEON_CELL_LOW_NIBBLE_MASK, 0xA);
    assert_eq!(fountain_effect_from_byte(cell), FountainEffect::BadTaste);
    // dungeon_cell_class_of routes its dispatch through the named shift
    // and round-trips every named class.
    assert_eq!(dungeon_cell_class_of(0x00), DungeonCellClass::Passage);
    assert_eq!(dungeon_cell_class_of(0xFF), DungeonCellClass::RoomTrigger);
}

#[test]
fn tlk_double_quote_encoded_matches_spec() {
    // formats/tlk.md §9.2: the on-disk encoding of the printable
    // double quote (`"`) under the bit-7 XOR scheme is 0xA2 —
    // the byte runner uses this exact value to detect adjacent
    // quotes and collapse `""` to a single visible quote.
    assert_eq!(TLK_DOUBLE_QUOTE_ENCODED, 0xA2);
    assert_eq!(TLK_DOUBLE_QUOTE_ENCODED ^ TLK_TEXT_XOR_MASK, b'"');
}

#[test]
fn active_object_phase_byte_nibble_layout_matches_spec() {
    // active-objects.md §3 and formats/ool.md §4: byte 6 packs
    // the animation phase in its low nibble and the direction-step
    // counter in its high nibble. Promote both the low-nibble mask
    // and the high-nibble shift so animator and renderer share
    // the same source of truth.
    assert_eq!(ACTIVE_OBJECT_PHASE_LOW_NIBBLE_MASK, 0x0F);
    assert_eq!(ACTIVE_OBJECT_PHASE_DIRECTION_NIBBLE_SHIFT, 4);
    // A packed byte with direction-step counter 0x9 in the high
    // nibble and animation phase 0x3 in the low nibble must
    // separate cleanly through the published accessors.
    let packed = 0x93;
    assert_eq!(packed & ACTIVE_OBJECT_PHASE_LOW_NIBBLE_MASK, 0x03);
    assert_eq!(active_object_direction_step(packed), 0x09);
    // Boundary cases: an all-zero byte yields zero in both fields,
    // and an all-ones byte yields 0xF in both fields.
    assert_eq!(active_object_direction_step(0x00), 0x00);
    assert_eq!(active_object_direction_step(0xFF), 0x0F);
}

#[test]
fn first_dungeon_scene_byte_matches_spec_arithmetic() {
    // formats/cbt.md §7 and formats/dungeon-dat.md §2: the
    // scene-byte range for the eight dungeons is 33..=40, and the
    // zero-based DUNGEON.DAT record number is recovered by
    // subtracting FIRST_DUNGEON_SCENE_BYTE from the scene byte.
    assert_eq!(FIRST_DUNGEON_SCENE_BYTE, 33);
    assert_eq!(LAST_DUNGEON_SCENE_BYTE, 40);
    assert_eq!(
        (LAST_DUNGEON_SCENE_BYTE - FIRST_DUNGEON_SCENE_BYTE + 1) as usize,
        8,
    );
    // Round-trip through DungeonScene for the first and last entries.
    let deceit = DungeonScene::new(FIRST_DUNGEON_SCENE_BYTE).unwrap();
    assert_eq!(deceit.record, 0);
    let doom = DungeonScene::new(LAST_DUNGEON_SCENE_BYTE).unwrap();
    assert_eq!(doom.record, 7);
}

