/// `display-driver-abi.md §9.5`, general path: "The entry takes an
/// inclusive rectangle and a **signed row distance**: positive moves the
/// rectangle's contents one way, negative the other, and the sign is
/// folded into the row-walk direction so the copy never overlaps itself
/// destructively. ... When the copy finishes, the entry **blanks the
/// vacated band**: it saves the current drawing colour, fills the band
/// the contents moved out of with colour index `0`, and restores the
/// colour. The band is computed from the distance and its sign, so it is
/// the correct edge of the rectangle in either direction."
#[test]
fn display_surface_scrolls_rect_by_signed_distance_and_blanks_vacated_band() {
    let ramp = |surface: &mut EgaDisplaySurface| {
        for y in 0..16 {
            surface.fill_rect(normalize_clamp_pixel_rect(0, y, 15, y).unwrap(), y as u8);
        }
    };
    let rect = normalize_clamp_pixel_rect(0, 0, 15, 15).unwrap();

    // One text row up: the wrapper's fixed distance.
    let mut surface = EgaDisplaySurface::new();
    ramp(&mut surface);
    surface.set_current_color(7);
    surface.scroll_text_rect_up_one_row(rect);

    assert_eq!(surface.read_pixel(0, 0), Some(8));
    assert_eq!(surface.read_pixel(15, 7), Some(15));
    assert_eq!(surface.read_pixel(0, 8), Some(0));
    assert_eq!(surface.read_pixel(15, 15), Some(0));
    // The drawing colour is saved across the band blank and restored.
    assert_eq!(surface.current_color(), 7);

    // The distance argument is live, and not only in multiples of a cell:
    // three scanlines up vacates the bottom three rows.
    let mut surface = EgaDisplaySurface::new();
    ramp(&mut surface);
    surface.scroll_rect_rows(rect, -3);

    assert_eq!(surface.read_pixel(0, 0), Some(3));
    assert_eq!(surface.read_pixel(15, 12), Some(15));
    assert_eq!(surface.read_pixel(0, 13), Some(0));
    assert_eq!(surface.read_pixel(15, 15), Some(0));

    // The opposite sign scrolls the other way and blanks the other edge.
    let mut surface = EgaDisplaySurface::new();
    ramp(&mut surface);
    surface.scroll_rect_rows(rect, 3);

    assert_eq!(surface.read_pixel(0, 15), Some(12));
    assert_eq!(surface.read_pixel(15, 4), Some(1));
    assert_eq!(surface.read_pixel(0, 2), Some(0));
    assert_eq!(surface.read_pixel(15, 0), Some(0));
}

/// `display-driver-abi.md §9.5`: the entry "reads the descriptor's
/// render-target selector and has a **separate, complete body for the
/// hidden surface**, exactly like the fill, tile and glyph entries." An
/// earlier revision called `0x27` "strictly a right-side-text-panel
/// scroll"; that is withdrawn, so a hidden-surface scroll of an
/// arbitrary rectangle must be a real scroll rather than a no-op.
#[test]
fn display_dispatch_scroll_rect_runs_on_the_hidden_surface() {
    let mut surface = EgaDisplaySurface::new();
    surface.set_render_target(DisplayRenderTarget::Back);
    for y in 0..16 {
        surface.fill_back_rect(normalize_clamp_pixel_rect(0, y, 15, y).unwrap(), y as u8);
    }
    let rect = normalize_clamp_pixel_rect(0, 0, 15, 15).unwrap();

    assert_eq!(
        surface
            .execute(EgaDisplayOperation::ScrollRect {
                rect,
                rows: -(CH_CELL_SIDE as i32),
            })
            .unwrap(),
        EgaDispatchResult::None
    );

    assert_eq!(surface.back_pixels()[0], 8);
    assert_eq!(surface.back_pixels()[7 * DISPLAY_SURFACE_WIDTH + 15], 15);
    assert_eq!(surface.back_pixels()[8 * DISPLAY_SURFACE_WIDTH], 0);
    // The visible page was never touched.
    assert_eq!(surface.read_pixel(0, 0), Some(0));
}

/// `display-driver-abi.md §9.5`, message-panel fast path: "This path is
/// hardwired and ignores both the rest of the rectangle and the distance
/// argument", scrolls "exactly eight scanlines upward", and its exposed
/// band is "Not blanked."
#[test]
fn display_surface_message_panel_scroll_ignores_distance_and_leaves_band_unblanked() {
    // A non-zero ramp, so "kept its old value" is distinguishable from
    // "blanked to colour 0".
    let value = |y: usize| ((y % 15) + 1) as u8;
    let mut surface = EgaDisplaySurface::new();
    for y in MESSAGE_PANEL_SCROLL_TOP..=MESSAGE_PANEL_SCROLL_BOTTOM {
        surface.fill_rect(
            normalize_clamp_pixel_rect(
                MESSAGE_PANEL_SCROLL_LEFT_EDGE as i32,
                y as i32,
                MESSAGE_PANEL_SCROLL_RIGHT_EDGE as i32,
                y as i32,
            )
            .unwrap(),
            value(y),
        );
    }
    // A rectangle naming the panel's left edge, with a distance the fast
    // path must ignore.
    let rect =
        normalize_clamp_pixel_rect(MESSAGE_PANEL_SCROLL_LEFT_EDGE as i32, 88, 319, 199).unwrap();
    surface.scroll_rect_rows(rect, -1);

    // Eight scanlines up, whatever the caller asked for.
    assert_eq!(
        surface.read_pixel(MESSAGE_PANEL_SCROLL_LEFT_EDGE, 88),
        Some(value(96))
    );
    assert_eq!(
        surface.read_pixel(MESSAGE_PANEL_SCROLL_RIGHT_EDGE, 191),
        Some(value(199))
    );
    // The exposed bottom band keeps whatever it held; it is not blanked.
    assert_eq!(
        surface.read_pixel(MESSAGE_PANEL_SCROLL_LEFT_EDGE, 199),
        Some(value(199))
    );
    // Rows above the panel and columns left of it are untouched.
    assert_eq!(surface.read_pixel(0, 88), Some(0));
    assert_eq!(
        surface.read_pixel(MESSAGE_PANEL_SCROLL_LEFT_EDGE, 87),
        Some(0)
    );
}

#[test]
fn display_surface_draws_tiles_and_fixed_glyphs_to_front_buffer() {
    let mut surface = EgaDisplaySurface::new();
    let atlas = synthetic_tile_atlas(TileGraphicsDepth::Ega16);
    surface.blit_tile_at_pixel(&atlas, 3, 304, 184).unwrap();

    assert_eq!(surface.read_pixel(304, 184), Some(3));
    assert_eq!(surface.read_pixel(319, 199), Some(3));

    let mut font_bytes = vec![0u8; CH_FONT_LEN];
    let glyph = usize::from(b'A') * CH_CELL_SIDE;
    font_bytes[glyph] = 0b1000_0001;
    font_bytes[glyph + 1] = 0b0111_1110;
    let font = parse_ch_font(&font_bytes, "fixture").unwrap();
    surface
        .draw_fixed_glyph_cell(&font, b'A', 1, 1, 0x0e, 0x01)
        .unwrap();

    assert_eq!(surface.read_pixel(8, 8), Some(0x0e));
    assert_eq!(surface.read_pixel(9, 8), Some(0x01));
    assert_eq!(surface.read_pixel(9, 9), Some(0x0e));
}

#[test]
fn display_entries_have_real_back_buffer_bodies_per_abi_sections_6_8_and_9_2() {
    // `display-driver-abi.md §8`: "**Correction: both entries have real
    // back-buffer paths.** An earlier revision of this section said the
    // tile entry returned without drawing when the back buffer was
    // selected [...] and that selecting the back buffer made the glyph
    // entry a no-op. All three statements are withdrawn: each entry
    // branches to a dedicated back-buffer body, and both bodies draw for
    // real." §6 records the same for the clipped rectangle fill `0x3F`
    // and §9.2 for the pixel plot `0x30`. A no-op on the hidden surface
    // would leave the endgame and map-viewport fades dissolving stale
    // pixels.
    let mut surface = EgaDisplaySurface::new();
    surface
        .execute(EgaDisplayOperation::InitBackBuffer)
        .unwrap();
    surface
        .execute(EgaDisplayOperation::SetRenderTarget(
            DisplayRenderTarget::Back,
        ))
        .unwrap();

    // `0x3F` clipped rectangle fill.
    surface
        .execute(EgaDisplayOperation::SetCurrentColor(0x0c))
        .unwrap();
    let rect = normalize_clamp_pixel_rect(0, 0, 3, 3).unwrap();
    surface
        .execute(EgaDisplayOperation::FillClippedRect(rect))
        .unwrap();

    // `0x30` pixel plot.
    surface
        .execute(EgaDisplayOperation::SetCurrentColor(0x09))
        .unwrap();
    surface
        .execute(EgaDisplayOperation::PlotPixel { x: 100, y: 100 })
        .unwrap();

    // `0x51` 16-by-16 tile.
    let atlas = synthetic_tile_atlas(TileGraphicsDepth::Ega16);
    surface
        .execute(EgaDisplayOperation::DrawTile {
            atlas: &atlas,
            tile: 3,
            dst_x: 304,
            dst_y: 184,
        })
        .unwrap();

    // `0x5D` fixed-cell glyph.
    let mut font_bytes = vec![0u8; CH_FONT_LEN];
    let glyph = usize::from(b'A') * CH_CELL_SIDE;
    font_bytes[glyph] = 0b1000_0001;
    let font = parse_ch_font(&font_bytes, "fixture").unwrap();
    surface
        .execute(EgaDisplayOperation::DrawGlyph {
            font: &font,
            code: b'A',
            cell_x: 1,
            cell_y: 1,
            foreground: 0x0e,
            background: 0x01,
        })
        .unwrap();

    let back = surface.back_pixels();
    let at = |x: usize, y: usize| back[y * DISPLAY_SURFACE_WIDTH + x];
    assert_eq!(at(0, 0), 0x0c, "0x3F must fill the hidden surface for real");
    assert_eq!(at(3, 3), 0x0c);
    assert_eq!(at(4, 0), 0x00, "the fill must not spill past the rectangle");
    assert_eq!(at(100, 100), 0x09, "0x30 must plot on the hidden surface");
    assert_eq!(
        at(304, 184),
        3,
        "0x51 must stamp the tile on the hidden surface"
    );
    assert_eq!(at(319, 199), 3);
    assert_eq!(
        at(8, 8),
        0x0e,
        "0x5D must draw the glyph on the hidden surface"
    );
    assert_eq!(at(9, 8), 0x01, "and its background where the bit is clear");

    // None of it may leak onto the visible page while the selector names
    // the hidden surface.
    assert_eq!(surface.read_pixel(0, 0), Some(0));
    assert_eq!(surface.read_pixel(100, 100), Some(0));
    assert_eq!(surface.read_pixel(304, 184), Some(0));
    assert_eq!(surface.read_pixel(8, 8), Some(0));

    // `display-driver-abi.md §9.2` dispatch offset `0x33`: the line entry
    // re-points its pixel writer at the visible page before every pixel,
    // so it draws to the FRONT buffer even with the back buffer selected.
    surface
        .execute(EgaDisplayOperation::SetCurrentColor(0x0f))
        .unwrap();
    surface
        .execute(EgaDisplayOperation::DrawLine {
            x0: 0,
            y0: 60,
            x1: 3,
            y1: 60,
        })
        .unwrap();
    assert_eq!(surface.read_pixel(0, 60), Some(0x0f));
    assert_eq!(surface.read_pixel(3, 60), Some(0x0f));
    assert_eq!(
        surface.back_pixels()[60 * DISPLAY_SURFACE_WIDTH],
        0,
        "0x33 is front-buffer-only regardless of the selector"
    );
}

#[test]
fn display_surface_rejects_cropped_tile_and_glyph_draws() {
    let mut surface = EgaDisplaySurface::new();
    let atlas = synthetic_tile_atlas(TileGraphicsDepth::Ega16);

    let err = surface
        .blit_tile_at_pixel(&atlas, 3, 318, 198)
        .expect_err("cropped tile blit must fail");
    assert!(
        err.to_string().contains("forbidden fallback"),
        "unexpected error: {err}"
    );

    let font = parse_ch_font(&vec![0u8; CH_FONT_LEN], "fixture").unwrap();
    let err = surface
        .draw_fixed_glyph_cell(&font, b'A', DISPLAY_TEXT_COLUMNS, 0, 0x0e, 0x01)
        .expect_err("cropped glyph draw must fail");
    assert!(
        err.to_string().contains("forbidden fallback"),
        "unexpected error: {err}"
    );
}

#[test]
fn display_surface_title_tick_requires_injected_authored_frames() {
    let mut surface = EgaDisplaySurface::new();
    surface.set_current_color(0x03);
    surface.plot_pixel(54, 64);
    surface.plot_pixel(54, 65);
    surface.plot_pixel(120, 85);
    surface.plot_pixel(54, 114);

    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        surface.advance_title_tick();
    }));

    let payload = result.expect_err("missing title-tick frames must panic");
    let message = payload
        .downcast_ref::<String>()
        .map(String::as_str)
        .or_else(|| payload.downcast_ref::<&str>().copied())
        .expect("title-tick panic payload must be a string");
    assert!(message.contains("forbidden fallback"), "{message}");
    assert_eq!(surface.title_tick_frame(), 0);
    assert_eq!(surface.read_pixel(54, 64), Some(0x03));
    assert_eq!(surface.read_pixel(54, 65), Some(0x03));
    assert_eq!(surface.read_pixel(120, 85), Some(0x03));
    assert_eq!(surface.read_pixel(54, 114), Some(0x03));
    assert_eq!(surface.presented_frames(), 0);

    surface.present_frame();

    assert_eq!(surface.presented_frames(), 1);
}

#[test]
fn display_driver_dispatch_slots_map_byte_offsets_to_public_inventory() {
    assert_eq!(EGA_DRIVER_SLOT_COUNT, 38);
    assert_eq!(ega_driver_dispatch_slot(0x00), Some(0));
    assert_eq!(ega_driver_dispatch_slot(0x3f), Some(21));
    assert_eq!(ega_driver_dispatch_slot(0x42), Some(22));
    assert_eq!(ega_driver_dispatch_slot(0x6f), Some(37));
    assert_eq!(ega_driver_dispatch_slot(0x40), None);
    assert_eq!(ega_driver_dispatch_slot(0x72), None);
    assert_eq!(ega_driver_dispatch_offset(21), Some(0x3f));
    assert_eq!(ega_driver_dispatch_offset(22), Some(0x42));
    assert_eq!(ega_driver_dispatch_offset(38), None);
}

#[test]
fn display_driver_executes_back_buffer_copy_and_front_fill_boundaries() {
    let mut surface = EgaDisplaySurface::new();
    let rect = normalize_clamp_pixel_rect(2, 2, 4, 3).unwrap();

    assert_eq!(
        surface.execute(EgaDisplayOperation::ScreenHeight).unwrap(),
        EgaDispatchResult::ScreenHeight(200)
    );
    assert_eq!(
        surface
            .execute(EgaDisplayOperation::InitBackBuffer)
            .unwrap(),
        EgaDispatchResult::BackBufferSegment(0)
    );
    assert!(surface.back_buffer_active());
    surface
        .execute(EgaDisplayOperation::SetRenderTarget(
            DisplayRenderTarget::Back,
        ))
        .unwrap();
    surface
        .execute(EgaDisplayOperation::SetCurrentColor(0x0d))
        .unwrap();

    surface
        .execute(EgaDisplayOperation::FillClippedRect(rect))
        .unwrap();
    assert_eq!(surface.read_pixel(2, 2), Some(0));

    surface
        .execute(EgaDisplayOperation::FillBackRect { rect, color: 0x1e })
        .unwrap();
    assert_eq!(surface.back_pixels()[2 * DISPLAY_SURFACE_WIDTH + 2], 0x0e);
    assert_eq!(surface.read_pixel(2, 2), Some(0));

    surface
        .execute(EgaDisplayOperation::DissolveBackToFront(rect))
        .unwrap();
    assert_eq!(surface.read_pixel(2, 2), Some(0x0e));
    assert_eq!(surface.read_pixel(4, 3), Some(0x0e));
    assert_eq!(surface.read_pixel(5, 3), Some(0));

    surface
        .execute(EgaDisplayOperation::ReleaseBackBuffer)
        .unwrap();
    assert!(!surface.back_buffer_active());
    assert_eq!(surface.render_target(), DisplayRenderTarget::Front);
    assert!(surface.back_pixels().iter().all(|pixel| *pixel == 0));
}

#[test]
fn display_driver_dissolve_progresses_in_deterministic_partial_order() {
    let mut surface = EgaDisplaySurface::new();
    let rect = normalize_clamp_pixel_rect(0, 0, 3, 2).unwrap();
    surface.fill_back_rect(rect, 0x0a);
    let mut dissolve = EgaDissolveState::new(rect);

    assert_eq!(dissolve.total_pixels(), 12);
    assert_eq!(surface.dissolve_back_to_front_step(&mut dissolve, 5), 5);
    assert_eq!(dissolve.copied_pixels(), 5);
    assert_eq!(dissolve.remaining_pixels(), 7);
    assert!(!dissolve.is_finished());
    assert_eq!(
        surface
            .front_pixels()
            .iter()
            .filter(|pixel| **pixel == 0x0a)
            .count(),
        5
    );

    assert_eq!(
        surface.dissolve_back_to_front_step(&mut dissolve, usize::MAX),
        7
    );
    assert!(dissolve.is_finished());
    for y in rect.y0..=rect.y1 {
        for x in rect.x0..=rect.x1 {
            assert_eq!(surface.read_pixel(x, y), Some(0x0a));
        }
    }
}

#[test]
fn display_driver_executes_front_buffer_tile_glyph_pixel_and_title_ops() {
    let mut surface = EgaDisplaySurface::new();
    let frames =
        TitleTickFrameSet::from_palette_indices(vec![0x0d; TITLE_TICK_FRAME_SET_BYTES], "fixture")
            .unwrap();
    surface.set_title_tick_frames(frames);
    let atlas = synthetic_tile_atlas(TileGraphicsDepth::Ega16);
    surface
        .execute(EgaDisplayOperation::SetRenderTarget(
            DisplayRenderTarget::Back,
        ))
        .unwrap();
    surface
        .execute(EgaDisplayOperation::DrawTile {
            atlas: &atlas,
            tile: 5,
            dst_x: 0,
            dst_y: 0,
        })
        .unwrap();
    assert_eq!(surface.read_pixel(0, 0), Some(0));

    surface
        .execute(EgaDisplayOperation::SetRenderTarget(
            DisplayRenderTarget::Front,
        ))
        .unwrap();
    surface
        .execute(EgaDisplayOperation::DrawTile {
            atlas: &atlas,
            tile: 5,
            dst_x: 0,
            dst_y: 0,
        })
        .unwrap();
    assert_eq!(surface.read_pixel(0, 0), Some(5));

    let mut font_bytes = vec![0u8; CH_FONT_LEN];
    let glyph = usize::from(b'Z') * CH_CELL_SIDE;
    font_bytes[glyph] = 0b1000_0000;
    let font = parse_ch_font(&font_bytes, "fixture").unwrap();
    surface
        .execute(EgaDisplayOperation::DrawGlyph {
            font: &font,
            code: b'Z',
            cell_x: 2,
            cell_y: 0,
            foreground: 0x0c,
            background: 0x02,
        })
        .unwrap();
    assert_eq!(surface.read_pixel(16, 0), Some(0x0c));
    assert_eq!(surface.read_pixel(17, 0), Some(0x02));

    surface
        .execute(EgaDisplayOperation::SetCurrentColor(0x1f))
        .unwrap();
    surface
        .execute(EgaDisplayOperation::DrawLine {
            x0: 0,
            y0: 4,
            x1: 2,
            y1: 4,
        })
        .unwrap();
    assert_eq!(surface.read_pixel(0, 4), Some(0x0f));
    assert_eq!(surface.read_pixel(2, 4), Some(0x0f));
    assert_eq!(surface.read_pixel(3, 4), Some(5));

    surface
        .execute(EgaDisplayOperation::PlotPixel { x: 319, y: 199 })
        .unwrap();
    assert_eq!(
        surface
            .execute(EgaDisplayOperation::ReadPixel { x: 319, y: 199 })
            .unwrap(),
        EgaDispatchResult::Pixel(0x0f)
    );

    assert_eq!(
        surface
            .execute(EgaDisplayOperation::AdvanceTitleTick)
            .unwrap(),
        EgaDispatchResult::Rect(DisplayPixelRect {
            x0: TITLE_TICK_FRAME_X as usize,
            y0: TITLE_TICK_FRAME_Y as usize,
            x1: (TITLE_TICK_FRAME_X + TITLE_TICK_FRAME_WIDTH - 1) as usize,
            y1: (TITLE_TICK_FRAME_Y + TITLE_TICK_FRAME_HEIGHT - 1) as usize,
        })
    );

    surface.execute(EgaDisplayOperation::PresentFrame).unwrap();
    assert_eq!(surface.presented_frames(), 1);
}

#[test]
fn display_driver_rejects_cropped_pixel_and_line_primitives() {
    let mut surface = EgaDisplaySurface::new();

    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        surface.plot_pixel(DISPLAY_SURFACE_WIDTH, 0);
    }));
    let payload = result.expect_err("out-of-bounds direct pixel plot must panic");
    let message = payload
        .downcast_ref::<String>()
        .map(String::as_str)
        .or_else(|| payload.downcast_ref::<&str>().copied())
        .expect("pixel plot panic payload must be a string");
    assert!(message.contains("forbidden fallback"), "{message}");

    let err = surface
        .execute(EgaDisplayOperation::ReadPixel {
            x: DISPLAY_SURFACE_WIDTH,
            y: 0,
        })
        .expect_err("out-of-bounds dispatch read must fail");
    assert!(
        err.to_string().contains("forbidden fallback"),
        "unexpected error: {err}"
    );

    let err = surface
        .execute(EgaDisplayOperation::PlotPixel {
            x: DISPLAY_SURFACE_WIDTH,
            y: 0,
        })
        .expect_err("out-of-bounds dispatch pixel plot must fail");
    assert!(
        err.to_string().contains("forbidden fallback"),
        "unexpected error: {err}"
    );

    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        surface
            .execute(EgaDisplayOperation::DrawLine {
                x0: -2,
                y0: 4,
                x1: 2,
                y1: 4,
            })
            .unwrap();
    }));
    let payload = result.expect_err("cropped display line must panic");
    let message = payload
        .downcast_ref::<String>()
        .map(String::as_str)
        .or_else(|| payload.downcast_ref::<&str>().copied())
        .expect("line panic payload must be a string");
    assert!(message.contains("forbidden fallback"), "{message}");
}

#[test]
fn display_driver_loaded_tile_graphics_save_restore_and_plane_swap() {
    let surface = EgaDisplaySurface::new();
    let mut atlas = TileAtlas {
        depth: TileGraphicsDepth::Ega16,
        pixels: vec![0; TILE_ATLAS_TILE_PIXELS * 3],
        dungeon_billboards: None,
        dungeon_sprites: None,
    };
    atlas.pixels[0] = 0x02;
    atlas.pixels[TILE_ATLAS_TILE_PIXELS] = 0x04;
    atlas.pixels[TILE_ATLAS_TILE_PIXELS * 2] = 0x06;
    let mut saved = EgaLoadedTileGraphicsSave::default();

    assert!(!saved.has_saved_pixels());
    let mut surface = surface;
    surface
        .execute(EgaDisplayOperation::SaveLoadedTileGraphics {
            atlas: &atlas,
            saved: &mut saved,
        })
        .unwrap();
    assert!(saved.has_saved_pixels());

    surface
        .execute(EgaDisplayOperation::SwapLoadedTileRedGreenPlanes {
            atlas: &mut atlas,
            tile_range: 0..2,
        })
        .unwrap();
    assert_eq!(atlas.pixels[0], 0x04);
    assert_eq!(atlas.pixels[TILE_ATLAS_TILE_PIXELS], 0x02);
    assert_eq!(atlas.pixels[TILE_ATLAS_TILE_PIXELS * 2], 0x06);

    surface
        .execute(EgaDisplayOperation::RestoreLoadedTileGraphics {
            atlas: &mut atlas,
            saved: &saved,
        })
        .unwrap();
    assert_eq!(atlas.pixels[0], 0x02);
    assert_eq!(atlas.pixels[TILE_ATLAS_TILE_PIXELS], 0x04);
    assert_eq!(atlas.pixels[TILE_ATLAS_TILE_PIXELS * 2], 0x06);
}

#[test]
fn chest_content_roll_die_and_secondary_attempt_formula_match_spec() {
    // containers.md §4: chest content gates use a `1..=30` die,
    // and the secondary-pool attempt count is `floor(chest_class
    // / 2) + 1`. Promote the die size, the divisor, and the
    // attempt bias so chest_primary_pool_row_succeeds and
    // chest_secondary_pool_attempts do not bake `30`, `2`, and
    // `+1` as bare literals.
    assert_eq!(CHEST_CONTENT_ROLL_DIE, 30);
    assert_eq!(CHEST_SECONDARY_POOL_ATTEMPT_DIVISOR, 2);
    assert_eq!(CHEST_SECONDARY_POOL_ATTEMPT_BIAS, 1);
    // Attempt count grows linearly with chest class.
    assert_eq!(
        chest_secondary_pool_attempts(0),
        CHEST_SECONDARY_POOL_ATTEMPT_BIAS
    );
    assert_eq!(chest_secondary_pool_attempts(8), 5);
    assert_eq!(chest_secondary_pool_attempts(30), 16);
}

#[test]
fn rare_reagent_harvest_quantity_span_matches_min_max_band() {
    // containers.md §5: the rare-reagent harvest rolls in the
    // inclusive `2..=15` range; the modulus on the seed must be
    // `MAX - MIN + 1` so every value in that band is reachable.
    // Promote the span so rare_reagent_harvest_quantity does not
    // bake `14` as a bare modulus literal.
    assert_eq!(
        RARE_REAGENT_HARVEST_QUANTITY_SPAN,
        RARE_REAGENT_HARVEST_QUANTITY_MAX - RARE_REAGENT_HARVEST_QUANTITY_MIN + 1
    );
    assert_eq!(RARE_REAGENT_HARVEST_QUANTITY_SPAN, 14);
    // Every seed value still lands inside the published band.
    for seed in 0u8..=u8::MAX {
        let q = rare_reagent_harvest_quantity(seed);
        assert!(
            (RARE_REAGENT_HARVEST_QUANTITY_MIN..=RARE_REAGENT_HARVEST_QUANTITY_MAX).contains(&q)
        );
    }
}

#[test]
fn potion_variation_threshold_constants_match_spec() {
    // inventory.md §7: the consumed-potion variation roll has
    // fourteen of sixteen outcomes (0..=13) preserve the chosen
    // colour's effect; roll value 14 forces Orange sleep; the
    // remaining outcome (15) substitutes a uniformly random
    // potion id from `0..=7`. Promote the threshold, the forced-
    // Orange exact roll, and the random-substitution mask so
    // potion_effect_index_after_variation does not bake `13`,
    // `14`, `0x0F`, and `0x07` as bare literals.
    assert_eq!(POTION_VARIATION_ROLL_MASK, 0x0F);
    assert_eq!(POTION_VARIATION_SELECTED_THRESHOLD, 13);
    assert_eq!(POTION_VARIATION_FORCED_ORANGE_ROLL, 14);
    assert_eq!(POTION_VARIATION_RANDOM_INDEX_MASK, 0x07);
    // Roll 0..=13 -> selected colour.
    for roll in 0u8..=POTION_VARIATION_SELECTED_THRESHOLD {
        assert_eq!(
            potion_effect_index_after_variation(POTION_RED_INDEX, roll, 0),
            POTION_RED_INDEX
        );
    }
    // Roll 14 -> Orange.
    assert_eq!(
        potion_effect_index_after_variation(POTION_RED_INDEX, 14, 0),
        POTION_ORANGE_INDEX
    );
    // Roll 15 -> random potion (the helper masks the random byte
    // to POTION_VARIATION_RANDOM_INDEX_MASK).
    assert_eq!(
        potion_effect_index_after_variation(POTION_RED_INDEX, 15, 3),
        3
    );
}

#[test]
fn weapon_range_arena_wide_cap_covers_full_arena_diagonal() {
    // catalogs/item-list.md §5.3: Magic Bow and Magic Axe use
    // non-adjacent range cap 15, which reaches every cell on the
    // eleven-by-eleven arena. The diagonal cells `(0, 0)` and
    // `(10, 10)` produce truncated Euclidean distance 14, so a
    // cap of 15 covers the full arena with one extra-cell
    // margin. Promote the value so the equipment range table
    // does not bake `15` as a bare row entry.
    assert_eq!(WEAPON_RANGE_ARENA_WIDE_CAP, 15);
    // Both arena-wide weapons publish this cap.
    assert_eq!(
        equipment_weapon_range_cap(EQUIPMENT_ID_MAGIC_BOW).unwrap(),
        WEAPON_RANGE_ARENA_WIDE_CAP
    );
    // EQUIPMENT_ID 38 is Magic Axe (catalog §5.3 row).
    assert_eq!(
        equipment_weapon_range_cap(38).unwrap(),
        WEAPON_RANGE_ARENA_WIDE_CAP
    );
    // Sanity: the cap is at least the integer-truncated full
    // arena diagonal so every cell is reachable.
    // sqrt(10*10 + 10*10) = sqrt(200) ≈ 14.14 → truncates to 14.
    let max_dx = (COMBAT_ARENA_SIDE - 1) as u32;
    let sq = max_dx * max_dx + max_dx * max_dx;
    let mut diagonal = 0u32;
    while (diagonal + 1) * (diagonal + 1) <= sq {
        diagonal += 1;
    }
    assert_eq!(diagonal, 14);
    assert!(WEAPON_RANGE_ARENA_WIDE_CAP >= diagonal as u8);
}

#[test]
fn combat_to_hit_bias_matches_spec_formula() {
    // systems/combat.md Section 11 "The score": the shared to-hit
    // helper computes `truncate_toward_zero((defender - attacker +
    // 30) / 2)` and compares it with one skewed `1..30` combat
    // roll. Promote the +30 bias so combat_to_hit_score does not
    // bake it as a bare literal. The bias is kept separate from
    // the JIMMY_CHEST_THRESHOLD_BIAS (also 30) because the two
    // contracts share only the magnitude, not the meaning.
    //
    // RETRACTIONS.md R334 withdrew this test's former formula
    // `(attacker - defender + 30) / 2`, and R335 withdrew its
    // "uniform random byte" draw; the `combat_to_hit_score(60, 50)
    // == 20` assertion those two lines justified goes with them.
    assert_eq!(COMBAT_TO_HIT_BIAS, 30);
    // Two equal-rating actors land at the bias / 2 = 15 score,
    // which the published table reads as a 50.8 % chance to hit.
    assert_eq!(combat_to_hit_score(50, 50), 15);
    assert_eq!(combat_to_hit_score(0, 0), 15);
    // A tougher defender raises the score - and a higher score is
    // a *worse* chance to hit.
    assert_eq!(combat_to_hit_score(50, 70), 25);
    assert_eq!(combat_to_hit_score(70, 50), 5);
}

#[test]
fn moonstone_burial_band_constants_match_spec() {
    // formats/saved-gam.md §7.2: Moonstone burying is accepted on
    // tile ids 4..=10 (a contiguous overworld band) plus 44 and
    // 45 (two extras). Promote the band edges and the extra
    // singletons so moonstone_burial_tile_accepted does not bake
    // the values as a bare match arm.
    assert_eq!(MOONSTONE_BURIAL_BAND_FIRST, 4);
    assert_eq!(MOONSTONE_BURIAL_BAND_LAST, 10);
    assert_eq!(MOONSTONE_BURIAL_TILE_EXTRA_A, 44);
    assert_eq!(MOONSTONE_BURIAL_TILE_EXTRA_B, 45);
    for tile in MOONSTONE_BURIAL_BAND_FIRST..=MOONSTONE_BURIAL_BAND_LAST {
        assert!(moonstone_burial_tile_accepted(tile));
    }
    assert!(moonstone_burial_tile_accepted(
        MOONSTONE_BURIAL_TILE_EXTRA_A
    ));
    assert!(moonstone_burial_tile_accepted(
        MOONSTONE_BURIAL_TILE_EXTRA_B
    ));
    // The two extras are adjacent but a tile just outside either
    // boundary is rejected.
    assert!(!moonstone_burial_tile_accepted(
        MOONSTONE_BURIAL_BAND_FIRST - 1
    ));
    assert!(!moonstone_burial_tile_accepted(
        MOONSTONE_BURIAL_BAND_LAST + 1
    ));
    assert!(!moonstone_burial_tile_accepted(
        MOONSTONE_BURIAL_TILE_EXTRA_B + 1
    ));
}

