#[test]
fn dawn_dusk_hour_constants_match_spec() {
    // lighting.md §3: the surface day-night cycle uses two named
    // gradient hours and six ten-minute levels. Promote the dawn
    // hour, dusk hour, step width, and last-minute boundary to
    // named constants so the daylight_base_value helper does not
    // bake `5`, `19`, `10`, and `59` as bare literals.
    assert_eq!(DAWN_HOUR, 5);
    assert_eq!(DUSK_HOUR, 19);
    assert_eq!(DAWN_DUSK_STEP_MINUTES, 10);
    assert_eq!(LAST_IN_HOUR_MINUTE, 59);
    assert_eq!(DAWN_DUSK_LAST_INDEX, 5);
    assert_eq!(DAWN_DUSK_LIGHT.len(), 6);
    // Six 10-minute levels exactly fill the dawn hour.
    assert_eq!(
        DAWN_DUSK_LIGHT.len() as u8 * DAWN_DUSK_STEP_MINUTES,
        60,
        "six ten-minute steps cover the full dawn/dusk hour"
    );
    // 05:00 starts at the darkest published level and 05:59
    // settles at the brightest published level.
    assert_eq!(
        daylight_base_value(DAWN_HOUR, 0, false, 0),
        DAWN_DUSK_LIGHT[0]
    );
    assert_eq!(
        daylight_base_value(DAWN_HOUR, LAST_IN_HOUR_MINUTE, false, 0),
        DAWN_DUSK_LIGHT[DAWN_DUSK_LAST_INDEX]
    );
    // 19:00 starts at the brightest level (dusk reverses the
    // gradient) and 19:59 settles at the darkest.
    assert_eq!(
        daylight_base_value(DUSK_HOUR, 0, false, 0),
        DAWN_DUSK_LIGHT[DAWN_DUSK_LAST_INDEX]
    );
    assert_eq!(
        daylight_base_value(DUSK_HOUR, LAST_IN_HOUR_MINUTE, false, 0),
        DAWN_DUSK_LIGHT[0]
    );
    // 04:59 and 20:00 are full darkness on the surface.
    assert_eq!(
        daylight_base_value(DAWN_HOUR - 1, LAST_IN_HOUR_MINUTE, false, 0),
        FULL_DARKNESS
    );
    assert_eq!(
        daylight_base_value(DUSK_HOUR + 1, 0, false, 0),
        FULL_DARKNESS
    );
    // `lighting.md §3`: the plane/floor forced-dark test is on the party's Z
    // "read as an unsigned byte: any Z with its high bit set - that is, any
    // value above one hundred twenty-seven". The Underworld plane and a
    // below-entry town floor both carry `0xFF`.
    assert_eq!(daylight_base_value(12, 0, true, 0), FULL_DARKNESS);
    assert_eq!(daylight_base_value(12, 0, false, 0xFF), FULL_DARKNESS);
    assert_eq!(
        daylight_base_value(12, 0, false, FORCED_DARK_MIN_DEPTH_Z),
        FULL_DARKNESS
    );

    // The same section is explicit that it "does **not** select ordinary
    // dungeon levels: a dungeon level index counts upward from zero at the top
    // of the stack, so it never sets the high bit, and the ambient value
    // computed while the party is inside a dungeon is simply whatever the clock
    // produces."
    //
    // This assertion previously read `daylight_base_value(12, 0, false, 1) ==
    // FULL_DARKNESS` under the comment "dungeon depths force full darkness".
    // That is the earlier wording §3 withdraws, and it passed only because the
    // engine still implemented the retracted rule — the test and the defect
    // were introduced together and protected each other.
    assert_ne!(daylight_base_value(12, 0, false, 1), FULL_DARKNESS);
    assert_eq!(
        daylight_base_value(12, 0, false, 1),
        daylight_base_value(12, 0, false, 0),
        "an ordinary dungeon level takes whatever the clock produces",
    );
    for depth in 1..FORCED_DARK_MIN_DEPTH_Z {
        assert_ne!(
            daylight_base_value(12, 0, false, depth),
            FULL_DARKNESS,
            "depth {depth} has no high bit and must not force darkness",
        );
    }
}

#[test]
fn town_cannon_named_constants_match_spec() {
    // vehicles.md §8: the town F-Fire path traces a short fixed
    // line for the first blocking target, and on an active-object
    // hit it reduces the shared moral-standing selector by five
    // units (floored at zero by the karma helper). Promote both
    // numbers to named constants so the F-Fire handler does not
    // bake `3` and `5` as bare literals.
    assert_eq!(TOWN_CANNON_RANGE_CELLS, 3);
    assert_eq!(TOWN_CANNON_HIT_KARMA_DEBIT, 5);
    // The town cannon range is the same magnitude as the ship
    // broadside range, but the spec keeps them as independent
    // contracts (one ship-only, one town-only). Both being 3 is
    // a coincidence of the published data, not a shared constant.
    assert_eq!(
        TOWN_CANNON_RANGE_CELLS as u8, SHIP_BROADSIDE_RANGE_CELLS,
        "spec keeps these contracts independent even though the v1 \
             values both happen to be three"
    );
}

#[test]
fn random_encounter_threshold_band_constants_match_spec_table() {
    // encounters.md §3: each row of the surface threshold table is
    // a paired (day, night) value keyed on a tile band. Promote
    // each value to a named constant so the table-driven helper
    // does not encode the numbers as bare literals.
    assert_eq!(RANDOM_ENCOUNTER_SAFE_TILE_FIRST, 0x20);
    assert_eq!(RANDOM_ENCOUNTER_SAFE_TILE_LAST, 0x26);
    assert_eq!(RANDOM_ENCOUNTER_SAFE_DAY_THRESHOLD, 0);
    assert_eq!(RANDOM_ENCOUNTER_SAFE_NIGHT_THRESHOLD, 3);
    assert_eq!(RANDOM_ENCOUNTER_WILDERNESS_SWAMP, 0x04);
    assert_eq!(RANDOM_ENCOUNTER_WILDERNESS_BAND_FIRST, 0x09);
    assert_eq!(RANDOM_ENCOUNTER_WILDERNESS_BAND_LAST, 0x0F);
    assert_eq!(RANDOM_ENCOUNTER_WILDERNESS_DAY_THRESHOLD, 2);
    assert_eq!(RANDOM_ENCOUNTER_WILDERNESS_NIGHT_THRESHOLD, 5);
    assert_eq!(RANDOM_ENCOUNTER_DEFAULT_DAY_THRESHOLD, 1);
    assert_eq!(RANDOM_ENCOUNTER_DEFAULT_NIGHT_THRESHOLD, 4);
    // Spot-check that the threshold function still returns the
    // documented value for each band, by day and by night.
    let day = RANDOM_ENCOUNTER_NIGHT_HOUR_LAST + 1;
    let night = 0;
    for safe_tile in RANDOM_ENCOUNTER_SAFE_TILE_FIRST..=RANDOM_ENCOUNTER_SAFE_TILE_LAST {
        assert_eq!(
            random_encounter_threshold(false, safe_tile, day),
            RANDOM_ENCOUNTER_SAFE_DAY_THRESHOLD
        );
        assert_eq!(
            random_encounter_threshold(false, safe_tile, night),
            RANDOM_ENCOUNTER_SAFE_NIGHT_THRESHOLD
        );
    }
    assert_eq!(
        random_encounter_threshold(false, RANDOM_ENCOUNTER_WILDERNESS_SWAMP, day),
        RANDOM_ENCOUNTER_WILDERNESS_DAY_THRESHOLD
    );
    assert_eq!(
        random_encounter_threshold(false, RANDOM_ENCOUNTER_WILDERNESS_SWAMP, night),
        RANDOM_ENCOUNTER_WILDERNESS_NIGHT_THRESHOLD
    );
    for tile in RANDOM_ENCOUNTER_WILDERNESS_BAND_FIRST..=RANDOM_ENCOUNTER_WILDERNESS_BAND_LAST {
        assert_eq!(
            random_encounter_threshold(false, tile, day),
            RANDOM_ENCOUNTER_WILDERNESS_DAY_THRESHOLD
        );
        assert_eq!(
            random_encounter_threshold(false, tile, night),
            RANDOM_ENCOUNTER_WILDERNESS_NIGHT_THRESHOLD
        );
    }
    // Any other surface tile uses the default band.
    assert_eq!(
        random_encounter_threshold(false, 0x30, day),
        RANDOM_ENCOUNTER_DEFAULT_DAY_THRESHOLD
    );
    assert_eq!(
        random_encounter_threshold(false, 0x30, night),
        RANDOM_ENCOUNTER_DEFAULT_NIGHT_THRESHOLD
    );
}

#[test]
fn npc_pathfind_visit_stamp_encodes_direction_in_high_nibble() {
    // npc-schedules.md §8.2: BFS overwrites each visited cell with
    // `direction << 4`. The shift width and seed value should be
    // named so workspace-builder code does not bake `4` and `0x40`
    // as bare literals.
    assert_eq!(NPC_PATHFIND_DIRECTION_SHIFT, 4);
    assert_eq!(NPC_PATHFIND_START_SEED, 0x40);
    // Visit stamp for each cardinal direction lands in the high
    // nibble exactly, leaving the low nibble clear so the cell's
    // pre-existing marker (open / goal sentinel) can still be read
    // by BFS via capture-before-write.
    assert_eq!(npc_pathfind_visit_stamp(NPC_PATH_DIR_WEST), 0x10);
    assert_eq!(npc_pathfind_visit_stamp(NPC_PATH_DIR_SOUTH), 0x20);
    assert_eq!(npc_pathfind_visit_stamp(NPC_PATH_DIR_EAST), 0x30);
    assert_eq!(npc_pathfind_visit_stamp(NPC_PATH_DIR_NORTH), 0x40);
    // The start-cell seed is by construction the north-direction
    // visit stamp.
    assert_eq!(
        NPC_PATHFIND_START_SEED,
        npc_pathfind_visit_stamp(NPC_PATH_DIR_NORTH)
    );
}

#[test]
fn town_rest_hour_wrap_uses_compatibility_subtrahend() {
    // rest-and-camp.md §4: "If current hour plus digit exceeds 23,
    // the original subtracts 23 rather than applying a normal
    // modulo-24 wrap; preserve that compatibility edge."
    assert_eq!(TOWN_REST_HOUR_WRAP_SUBTRAHEND, 23);
    assert_eq!(TOWN_REST_TICK_BUDGET, 144);
    assert_eq!(TOWN_REST_DURATION_DIGIT_MAX, 9);
    // 22 + 2 = 24 → 24 - 23 = 1 (not modulo 0).
    assert_eq!(PlayState::town_rest_target_hour(22, 2), 1);
    // 23 + 1 = 24 → 24 - 23 = 1 (not modulo 0).
    assert_eq!(PlayState::town_rest_target_hour(23, 1), 1);
    // 23 + 9 = 32 → 32 - 23 = 9 (this is the documented edge —
    // ordinary modulo-24 would yield 8).
    assert_eq!(PlayState::town_rest_target_hour(23, 9), 9);
    // No-wrap path: 5 + 4 = 9 stays at 9.
    assert_eq!(PlayState::town_rest_target_hour(5, 4), 9);
    // Equal-to-23 boundary stays untouched (target == 23, not > 23).
    assert_eq!(PlayState::town_rest_target_hour(22, 1), 23);
}

#[test]
fn wind_drift_named_constants_match_spec() {
    // weather.md §2: the autonomous wind-drift gates use three
    // published thresholds. Promote each one to a named constant
    // so call sites do not pass `0x3f`, `5`, or `192` as raw
    // literals.
    assert_eq!(WIND_DRIFT_OUTER_ROLL_MASK, 0x3F);
    assert_eq!(WIND_DRIFT_CANDIDATE_MODULUS, 5);
    assert_eq!(WIND_DRIFT_CALM_ACCEPT_MIN, 192);
    // Outer gate: zero, and any roll whose low six bits are zero,
    // is accepted. Every roll with at least one set bit in that
    // window is rejected.
    assert!(WindState::autonomous_drift_outer_accepted(0));
    assert!(WindState::autonomous_drift_outer_accepted(0x40));
    assert!(WindState::autonomous_drift_outer_accepted(0xC0));
    for r in 1u8..=63 {
        assert!(!WindState::autonomous_drift_outer_accepted(r));
    }
    // Calm acceptance: strictly below the published threshold is
    // rejected; the threshold and above is accepted.
    assert_eq!(
        WindState::autonomous_drift_accept_candidate(0, WIND_DRIFT_CALM_ACCEPT_MIN - 1),
        None
    );
    assert_eq!(
        WindState::autonomous_drift_accept_candidate(0, WIND_DRIFT_CALM_ACCEPT_MIN),
        Some(WindState::Calm)
    );
}

/// `dungeon-mode.md §12.4` class-to-glyph-and-font table, in full.
///
/// Two rows here previously asserted the wrong output. Class `0x5?`
/// asserted glyph `0x12`, which is exact byte `0x68`'s published
/// up-and-down arrow — two classes mapping to one glyph code — where
/// §12.4 gives `0x5?` a **vector** fountain drawing. Class `0x8?`
/// asserted glyph `0x18`, the `0x0?` up-arrow, where §12.4 gives it the
/// **vector** energy-field drawing. Both are published in §12.5.
#[test]
fn dungeon_minimap_glyph_matches_published_class_table() {
    use DungeonMinimapGlyph as G;

    // Passage detail glyphs require bit 0x08 set on a 0x0? cell.
    assert_eq!(dungeon_minimap_glyph(0x00), None);
    assert_eq!(dungeon_minimap_glyph(0x08), Some(G::text(0x18))); // Up arrow
    assert_eq!(dungeon_minimap_glyph(0x10), Some(G::runic(0x2E))); // Up ladder
    assert_eq!(dungeon_minimap_glyph(0x20), Some(G::runic(0x2D))); // Down ladder
    assert_eq!(dungeon_minimap_glyph(0x30), Some(G::runic(0x2F))); // Two-way ladder
    assert_eq!(dungeon_minimap_glyph(0x40), Some(G::runic(0x70))); // Closed chest
    // §12.4: the fountain class is a vector drawing, not a font glyph.
    assert_eq!(dungeon_minimap_glyph(0x50), Some(G::Fountain));
    assert_eq!(dungeon_minimap_glyph(0x5F), Some(G::Fountain));
    // Exact 0x6? bytes carve out specific glyphs before the band.
    assert_eq!(dungeon_minimap_glyph(0x60), Some(G::text(0x19))); // Down arrow
    assert_eq!(dungeon_minimap_glyph(0x61), Some(G::runic(0x71))); // Hidden/fall pit
    assert_eq!(dungeon_minimap_glyph(0x69), Some(G::runic(0x71))); // Hidden/fall pit
    assert_eq!(dungeon_minimap_glyph(0x68), Some(G::text(0x12))); // Up-and-down arrow
    assert_eq!(dungeon_minimap_glyph(0x62), Some(G::runic(0x72))); // Other 0x6?
    assert_eq!(dungeon_minimap_glyph(0x6F), Some(G::runic(0x72)));
    // Blank classes.
    assert_eq!(dungeon_minimap_glyph(0x70), None);
    assert_eq!(dungeon_minimap_glyph(0x90), None);
    // §12.4: the energy-field class is a vector drawing too.
    assert_eq!(dungeon_minimap_glyph(0x80), Some(G::EnergyField));
    assert_eq!(dungeon_minimap_glyph(0x8F), Some(G::EnergyField));
    // Wall classes.
    assert_eq!(dungeon_minimap_glyph(0xB0), Some(G::text(0x7F)));
    assert_eq!(dungeon_minimap_glyph(0xB1), Some(G::runic(0x74)));
    assert_eq!(dungeon_minimap_glyph(0xC0), Some(G::runic(0x75)));
    assert_eq!(dungeon_minimap_glyph(0xD0), Some(G::runic(0x76)));
    assert_eq!(dungeon_minimap_glyph(0xE0), Some(G::runic(0x77)));
    // Door/room families.
    assert_eq!(dungeon_minimap_glyph(0xA0), Some(G::runic(0x73)));
    assert_eq!(dungeon_minimap_glyph(0xF0), Some(G::runic(0x73)));
}

/// `dungeon-mode.md §12.3`: "Most classes select the **runic** font. Four
/// deliberately select the **text** font instead: three of them for
/// directional arrows the runic font does not have, and one for a solid
/// block." Those four are the `0x0?` up-arrow, exact `0x60`'s down-arrow,
/// exact `0x68`'s up-and-down arrow, and `0xB0` bedrock — and nothing
/// else.
#[test]
fn dungeon_minimap_text_font_classes_are_exactly_the_published_four() {
    let text_font_bytes: Vec<u8> = (0u8..=255)
        .filter(|byte| {
            matches!(
                dungeon_minimap_glyph(*byte),
                Some(DungeonMinimapGlyph::Font {
                    font: DungeonMinimapFont::Text,
                    ..
                })
            )
        })
        .collect();
    // Every 0x0? byte with the visit-marker bit is the up-arrow class.
    let expected: Vec<u8> = (0u8..=255)
        .filter(|byte| {
            (*byte < 0x10 && byte & DUNGEON_VISIT_MARKER_BIT != 0)
                || *byte == 0x60
                || *byte == 0x68
                || *byte == 0xB0
        })
        .collect();
    assert_eq!(text_font_bytes, expected);
}

/// `dungeon-mode.md §12.4`: no two classes may map to the same font
/// glyph. This is the invariant the fountain class broke — it returned
/// `0x12`, exact byte `0x68`'s up-and-down arrow.
#[test]
fn dungeon_minimap_font_glyphs_do_not_collide_across_classes() {
    use std::collections::HashMap;

    // One representative byte per published row.
    let rows: [(&str, u8); 17] = [
        ("0x0? up-arrow", 0x08),
        ("0x1? up ladder", 0x10),
        ("0x2? down ladder", 0x20),
        ("0x3? two-way ladder", 0x30),
        ("0x4? closed chest", 0x40),
        ("0x5? fountain", 0x50),
        ("0x60 down-arrow", 0x60),
        ("0x61/0x69 hidden pit", 0x61),
        ("0x68 up-and-down arrow", 0x68),
        ("other 0x6? trap", 0x62),
        ("0x8? energy field", 0x80),
        ("0xA?/0xF? heavy door", 0xA0),
        ("0xB0 bedrock", 0xB0),
        ("other 0xB? lattice", 0xB1),
        ("0xC? speckled diagonal", 0xC0),
        ("0xD? arch", 0xD0),
        ("0xE? filled rounded block", 0xE0),
    ];

    let mut seen: HashMap<u8, &str> = HashMap::new();
    for (label, byte) in rows {
        let Some(index) = dungeon_minimap_glyph(byte).and_then(|glyph| glyph.font_index()) else {
            continue;
        };
        if let Some(previous) = seen.insert(index, label) {
            panic!("glyph {index:#04x} claimed by both `{previous}` and `{label}`");
        }
    }
    // The party marker's arrowhead is a further distinct glyph.
    assert_eq!(DUNGEON_MINIMAP_PARTY_GLYPH.font_index(), Some(0x60));
    assert!(!seen.contains_key(&0x60));
}

#[test]
fn dungeon_walkability_matches_room_trigger_class_table() {
    // Public issue #1 / dungeon-mode.md: 0xA? helper cells and
    // 0xF? room-trigger cells are not rejected by ordinary forward
    // movement. 0xE? uses the same pass-through branch; only the
    // 0xB?..=0xD? wall/flavour classes block the forward gate.
    assert!(is_dungeon_walkable(0x00));
    assert!(is_dungeon_walkable(0xA0));
    assert!(is_dungeon_walkable(0xAF));
    assert!(is_dungeon_walkable(0xE0));
    assert!(is_dungeon_walkable(0xEF));
    assert!(is_dungeon_walkable(0xF0));
    assert!(is_dungeon_walkable(0xFF));
    assert!(!is_dungeon_walkable(0xB0));
    assert!(!is_dungeon_walkable(0xC0));
    assert!(!is_dungeon_walkable(0xD0));
    assert!(!dungeon_back_step_rejected(0xE0));
    assert!(dungeon_back_step_rejected(0xA0));
    assert!(dungeon_back_step_rejected(0xF0));
}

#[test]
fn tlk_ask_who_match_uses_the_published_first_four_character_rule() {
    // conversation.md §7.6: "For each active party slot in order, the
    // engine takes the first four characters of that member's name and
    // searches for them as a substring of the typed line. A hit counts
    // only at the start of the line or immediately after a literal space;
    // a hit in the middle of a longer word is rejected and the scan
    // continues with the next member."
    //
    // This replaces the whole-string equality matcher this engine used to
    // route 0x88 through, which the same section withdraws.
    let names: [&[u8]; 4] = [b"Avatar", b"Shamino", b"Iolo", b"Mariah"];
    assert_eq!(tlk_ask_who_match(b"Avatar", &names), 1);
    assert_eq!(tlk_ask_who_match(b"shamino", &names), 2);
    assert_eq!(tlk_ask_who_match(b"IOLO", &names), 3);
    assert_eq!(tlk_ask_who_match(b"Mariah", &names), 4);
    // Four characters is enough, and the rest of the line is ignored.
    assert_eq!(tlk_ask_who_match(b"Sham", &names), 2);
    assert_eq!(tlk_ask_who_match(b"Marianne of Britain", &names), 4);
    // A hit after a literal space counts.
    assert_eq!(tlk_ask_who_match(b"my friend Iolo", &names), 3);
    // A hit inside a longer word is rejected and the scan continues.
    assert_eq!(tlk_ask_who_match(b"triolo", &names), 0);
    // Empty input is its own early exit.
    assert_eq!(tlk_ask_who_match(b"", &names), 0);
    assert_eq!(tlk_ask_who_match(b"Dupre", &names), 0);
    // High-bit-encoded name on the engine side matches a plain typed
    // answer (the typed side is bit-7-stripped too).
    let obfuscated: [u8; 4] = [b'I' | 0x80, b'o' | 0x80, b'l' | 0x80, b'o' | 0x80];
    let obfuscated_names: [&[u8]; 1] = [obfuscated.as_slice()];
    assert_eq!(tlk_ask_who_match(b"iolo", &obfuscated_names), 1);
    // Empty roster slots are skipped.
    let with_blank: [&[u8]; 3] = [b"", b"Geoffrey", b""];
    assert_eq!(tlk_ask_who_match(b"Geoffrey", &with_blank), 2);
}

