#[test]
fn numeric_prompt_accumulates_digits_and_pops_on_backspace() {
    // input.md §8: numeric prompts apply value = value * 10 +
    // digit and treat Backspace as integer-division by ten.
    // Enter terminates and Discard leaves the accumulator alone.
    use NumericPromptAction::*;
    assert_eq!(numeric_prompt_action(b'3'), AppendDigit(3));
    assert_eq!(numeric_prompt_action(b'0'), AppendDigit(0));
    assert_eq!(numeric_prompt_action(b'9'), AppendDigit(9));
    assert_eq!(numeric_prompt_action(0x08), Pop);
    assert_eq!(numeric_prompt_action(b'\r'), Submit);
    assert_eq!(numeric_prompt_action(b'\n'), Submit);
    assert_eq!(numeric_prompt_action(0x1B), Discard);
    assert_eq!(numeric_prompt_action(b' '), Discard);
    assert_eq!(numeric_prompt_action(b'a'), Discard);

    // Building "1234" digit by digit.
    let mut v = 0u16;
    for digit in [1, 2, 3, 4] {
        v = numeric_prompt_apply(v, AppendDigit(digit));
    }
    assert_eq!(v, 1234);
    // Backspace removes one digit (1234 / 10 = 123).
    v = numeric_prompt_apply(v, Pop);
    assert_eq!(v, 123);
    // Submit/Discard leave the accumulator unchanged.
    assert_eq!(numeric_prompt_apply(v, Submit), 123);
    assert_eq!(numeric_prompt_apply(v, Discard), 123);
    // Pop on zero stays zero.
    assert_eq!(numeric_prompt_apply(0, Pop), 0);
    // Saturating cap: appending digits past u16::MAX clamps.
    assert_eq!(numeric_prompt_apply(u16::MAX, AppendDigit(9)), u16::MAX);
}

#[test]
fn tlk_payment_milestone_requires_live_beggar_speaker_and_aged_cooldown() {
    // `karma.md §4.1`: payment debits always, but only a live speaker of
    // actor class 108 can consume an already-aged threshold and award
    // standing. The payment does not increment the counter.
    let mut state = test_state(open_grid(), 1, 1);
    state.load_scheduled_npcs(&[
        NpcSlot {
            slot: 0,
            type_byte: 0,
            dialog_id: 0,
            schedule: [0; 16],
            name: None,
        },
        NpcSlot {
            slot: 1,
            type_byte: TLK_GOLD_PAYMENT_KARMA_SPEAKER_CLASS,
            dialog_id: 1,
            schedule: [0, 0, 0, 2, 2, 2, 1, 1, 1, 0, 0, 0, 0, 8, 16, 20],
            name: None,
        },
    ]);
    state.active_conversation_npc_slot = Some(1);
    state.gold = 50;
    state.moral_standing = 10;
    state.toll_progress = TOLL_PROGRESS_MILESTONE;
    let payments = [crate::conversation_session::ConversationGoldPayment {
        amount: 25,
        accepted: true,
    }];
    state.apply_tlk_gold_payments(&payments);
    // Gold debited and counter rolled over.
    assert_eq!(state.gold, 25);
    assert_eq!(state.toll_progress, 0);
    assert_eq!(state.moral_standing, 11);

    // A second fully aged qualifying payment that empties the purse adds
    // the nested +2 zero-gold bonus after the ordinary +1.
    state.toll_progress = TOLL_PROGRESS_MILESTONE;
    let drain = [crate::conversation_session::ConversationGoldPayment {
        amount: 25,
        accepted: true,
    }];
    state.apply_tlk_gold_payments(&drain);
    assert_eq!(state.gold, 0);
    assert_eq!(state.toll_progress, 0);
    assert_eq!(state.moral_standing, 14);

    // Below threshold: debit only, and payment itself does not age the byte.
    state.gold = 10;
    state.toll_progress = TOLL_PROGRESS_MILESTONE - 1;
    state.apply_tlk_gold_payments(&[crate::conversation_session::ConversationGoldPayment {
        amount: 1,
        accepted: true,
    }]);
    assert_eq!(state.gold, 9);
    assert_eq!(state.toll_progress, TOLL_PROGRESS_MILESTONE - 1);
    assert_eq!(state.moral_standing, 14);

    // The actor must still be live/linked when the payment is applied.
    state.npcs[0].active_object = None;
    state.toll_progress = TOLL_PROGRESS_MILESTONE;
    state.apply_tlk_gold_payments(&[crate::conversation_session::ConversationGoldPayment {
        amount: 1,
        accepted: true,
    }]);
    assert_eq!(state.gold, 8);
    assert_eq!(state.toll_progress, TOLL_PROGRESS_MILESTONE);
    assert_eq!(state.moral_standing, 14);
}

#[test]
fn ordinary_turns_age_the_payment_cooldown_and_combat_does_not() {
    // `karma.md §4.1`: ordinary world/town/dungeon actions increment the
    // saved cooldown once and saturate at 255. Combat has its own actor loop.
    let mut state = test_state(open_grid(), 1, 1);
    state.toll_progress = TOLL_PROGRESS_MILESTONE - 1;
    state.advance_turn_with_minutes(0);
    assert_eq!(state.toll_progress, TOLL_PROGRESS_MILESTONE);

    state.toll_progress = u8::MAX;
    state.advance_turn_with_minutes(0);
    assert_eq!(state.toll_progress, u8::MAX);

    state.toll_progress = 7;
    state.combat_active = true;
    state.advance_turn_with_minutes(0);
    assert_eq!(state.toll_progress, 7);
}

#[test]
fn shipped_return_to_view_strips_are_nineteen_across_by_four_down() {
    // `cleak/u5-spec#54` retraction 1: each record is four 32-byte rows,
    // nineteen tile bytes then thirteen bytes of padding. Verified
    // structurally against the shipped `MISCMAPS.DAT`: every visible
    // cell of every strip carries a real terrain byte and every padding
    // byte is zero, which is what makes the terrain-first cell rule
    // total for a loaded strip.
    let Some(game_dir) = crate::test_fixtures::configured_original_asset_dir() else {
        return;
    };
    let game_dir = game_dir.as_path();
    if !game_dir.join(MISCMAPS_DAT_FILE).exists() {
        return;
    }
    let strips = load_return_to_view_map_strips(game_dir)
        .expect("shipped MISCMAPS.DAT parses")
        .expect("shipped MISCMAPS.DAT is present");

    for strip in 0..RTV_STRIP_COUNT {
        let cells = &strips.strips[strip];
        assert_eq!(
            cells.len(),
            RTV_STRIP_VISIBLE_COLUMNS * RTV_STRIP_VISIBLE_ROWS
        );
        assert!(
            cells.iter().all(|tile| *tile != 0),
            "strip {strip} has an empty cell; the terrain-first draw rule assumes none"
        );
        assert!(
            cells.iter().all(|tile| *tile != RTV_TERRAIN_HELPER_OWNED),
            "strip {strip} ships a reserved helper-owned terrain byte"
        );
    }

    // The padding never reaches the preview: a transposed read would
    // have pulled it in.
    let bytes = std::fs::read(game_dir.join(MISCMAPS_DAT_FILE)).expect("MISCMAPS.DAT reads");
    for strip in 0..RTV_STRIP_COUNT {
        for row in 0..RTV_STRIP_VISIBLE_ROWS {
            let row_start = MISCMAPS_RTV_STRIP_SECTION_OFFSET
                + strip * RTV_STRIP_RECORD_BYTES
                + row * MISCMAPS_RTV_STRIP_ROW_STRIDE;
            let padding = &bytes
                [row_start + RTV_STRIP_VISIBLE_COLUMNS..row_start + MISCMAPS_RTV_STRIP_ROW_STRIDE];
            assert!(
                padding.iter().all(|byte| *byte == 0),
                "strip {strip} row {row} padding is not zero"
            );
        }
    }
}

#[test]
fn shipped_return_to_view_script_keeps_every_placed_actor_inside_the_strip() {
    // `#54`: "script coordinates never leave `x = 0..18` / `y = 0..3`,
    // so nothing is clipped and no clipping rule is needed". Replaying
    // the shipped stream must therefore never fail on a bounds check.
    let Some(game_dir) = crate::test_fixtures::configured_original_asset_dir() else {
        return;
    };
    let game_dir = game_dir.as_path();
    if !game_dir.join(MISCMAPS_DAT_FILE).exists() {
        return;
    }
    let assets = load_return_to_view_assets(game_dir)
        .expect("shipped MISCMAPS.DAT parses")
        .expect("shipped MISCMAPS.DAT is present");

    let playback = run_return_to_view_playback_until_restart(&assets.strips, &assets.script, 4096)
        .expect("the shipped Return-to-View stream replays without leaving the strip");

    assert!(playback.run.report.restart_seen);
    assert!(!playback.frames.is_empty());
    for frame in &playback.frames {
        for actor in frame.state.actors.iter().filter(|actor| actor.drawable) {
            assert!(
                usize::from(actor.x) < RTV_STRIP_VISIBLE_COLUMNS
                    && usize::from(actor.y) < RTV_STRIP_VISIBLE_ROWS,
                "actor at ({}, {}) left the strip",
                actor.x,
                actor.y
            );
        }
    }
}

#[test]
fn return_to_view_published_wait_cadence_constants() {
    // `cleak/u5-spec#54` (2026-08-22 resolution) retraction 2: there is
    // no fixed eight-tick wait. `0x03` runs its own argument byte,
    // `0x04`/`0x05` run 2 at their tails, `0x0B` runs 3 and `0x0D` runs
    // 7. Retraction 3: every preview tick polls the keyboard and any
    // pending key aborts immediately — there is no uninterruptible
    // phase and no ESC special case.
    assert_eq!(RTV_CELL_EFFECT_STEPS, 15);
    assert_eq!(RTV_CELL_EFFECT_FINAL_TICKS, 2);
    assert_eq!(RTV_FIXED_WIPE_STEPS, 5);
    assert_eq!(RTV_FIXED_WIPE_TRAILING_TICKS, 3);
    assert_eq!(RTV_FIXED_WIPE_TOTAL_TICKS, 8);
    assert_eq!(RTV_MOVE_ACTOR_AND_TICK_TICKS, 7);
    assert!(RTV_WAIT_EXITS_ON_KEYPRESS);
}

