#[test]
fn text_window_inner_width_and_centred_start_match_spec() {
    // text-output.md §4 (`RETRACTIONS.md` R344): a window whose corners
    // are columns 6 and 33 carries an inclusive-endpoint budget of 27 -
    // the last legal window-local column, NOT a character count. The row
    // holds twenty-eight; the twenty-ninth forces the wrap.
    assert_eq!(text_window_inner_width(6, 33), 27);
    assert_eq!(text_window_inner_width(0, 39), 39);
    // Inverted corners collapse to zero.
    assert_eq!(text_window_inner_width(20, 10), 0);
    assert_eq!(text_window_inner_width(15, 15), 0);

    // text-output.md §5: the centre branch measures against
    // `columns_in_window = bottom_right_x - top_left_x + 1`, one
    // MORE than the inclusive-endpoint budget above. Dropping the plus one agrees
    // on odd-length lines but shifts every even-length line one
    // whole cell left, so `column_count()` - not `inner_width()` -
    // is what the helper takes.
    let window = TextWindowDescriptor {
        top_left_x: 6,
        bottom_right_x: 33,
        ..TextWindowDescriptor::default()
    };
    assert_eq!(window.inner_width(), 27);
    assert_eq!(window.column_count(), 28);

    // Centred start column = (columns_in_window - line) / 2.
    assert_eq!(text_window_centred_start_column(28, 7), 10);
    assert_eq!(text_window_centred_start_column(28, 28), 0);
    // Lines wider than the window collapse to column 0 rather than
    // producing a negative offset.
    assert_eq!(text_window_centred_start_column(28, 30), 0);
    // Even split.
    assert_eq!(text_window_centred_start_column(40, 10), 15);

    // The printer's own form works from the columns still available
    // on the row and the index of the line's LAST character:
    // `(available - (len - 1)) / 2`. At the window's left edge it
    // agrees with the column-count form above.
    for line_chars in 1..=28u8 {
        assert_eq!(
            text_window_centred_start_column_from_cursor(window.inner_width(), 0, line_chars),
            text_window_centred_start_column(window.column_count(), line_chars),
            "line of {line_chars} characters",
        );
    }
    // An even-length line is exactly where the dropped plus one
    // would have shifted it one cell left of.
    assert_eq!(
        text_window_centred_start_column_from_cursor(27, 0, 10),
        9,
        "the (brx - tlx - len) / 2 form would have said 8",
    );
    // A mid-row cursor consumes the available columns.
    assert_eq!(text_window_centred_start_column_from_cursor(27, 7, 10), 5);
    // A line that cannot fit in what remains collapses to column 0.
    assert_eq!(text_window_centred_start_column_from_cursor(27, 20, 10), 0);
}

#[test]
fn centred_printer_uses_the_plus_one_column_count() {
    // text-output.md §5: a window spanning columns 0..=11 is TWELVE
    // columns wide, so an eight-character line starts at column 2
    // and ends in column 9. Centring against the eleven-cell wrap
    // width instead would have started it in column 1 - one whole
    // cell (eight pixels) left of the original.
    let mut system = TextWindowSystem::new();
    system.set_window_rect(0, 0, 0, 11, 2);
    system.emit_byte(TEXT_CTRL_CENTRE_ON);
    system.print_wrapped_string("abcdefgh");
    assert_eq!(system.cell(2, 0).unwrap().byte, b'a');
    assert_eq!(system.cell(9, 0).unwrap().byte, b'h');
    assert_eq!(system.cell(1, 0), None);

    // A seven-character line in the same window lands where the
    // dropped-plus-one form would also have put it, which is why
    // the defect showed as inconsistent centring between adjacent
    // lines of one block rather than a uniform shift.
    let mut system = TextWindowSystem::new();
    system.set_window_rect(0, 0, 0, 11, 2);
    system.emit_byte(TEXT_CTRL_CENTRE_ON);
    system.print_wrapped_string("abcdefg");
    assert_eq!(system.cell(2, 0).unwrap().byte, b'a');
}

#[test]
fn an_overlong_chunk_is_kept_whole_and_printed_from_column_zero() {
    // `text-output.md §6` (`RETRACTIONS.md` R346): "A word longer than the
    // row is **not** allowed to overflow the right edge. The collector never
    // gathers more characters than the row can still hold, so nothing is ever
    // written past `bottom_right_x`. When the collected chunk fills the
    // remaining row and contains no break byte to retreat to, the printer
    // keeps the whole chunk, first emits a line feed if the cursor is not
    // already at the window's left edge, and prints the chunk from column 0 of
    // the fresh row; the following chunk then continues on that same row at
    // the column where the first one stopped."
    //
    // `RETRACTIONS.md` R349 works exactly this case for the dungeon exit:
    // "With eight of sixteen columns left, the printer collects the eight
    // characters that still fit, finds no break byte, keeps that chunk, emits
    // a line feed because the cursor is not at the left edge, prints the chunk
    // from column 0, and the **next** chunk continues on the same row at
    // column eight." The rendered pixels are `Underworld!` whole on the new
    // row - the truncated `Underwor` is never printed in place.
    let mut system = TextWindowSystem::new();
    // The gameplay message window: columns 24..=39, sixteen cells
    // (`text-output.md §10.1`, `RETRACTIONS.md` R347).
    system.set_window_rect(0, 24, 11, 39, 23);
    for byte in b"Exit to " {
        system.emit_byte(*byte);
    }
    assert_eq!(system.active_cursor(), (8, 0));

    system.print_wrapped_string("Underworld!");

    let row_below: String = (24..=34)
        .map(|x| char::from(system.cell(x, 12).map(|cell| cell.byte).unwrap_or(b' ')))
        .collect();
    assert_eq!(row_below, "Underworld!");
    // Nothing was written past `bottom_right_x`, and nothing landed in the
    // eight columns the word did not fit into on the row above.
    for x in 32..=39 {
        assert_eq!(system.cell(x, 11), None, "column {x} of the entry row");
    }
    assert_eq!(system.active_cursor(), (11, 1));
}

#[test]
fn a_word_longer_than_a_full_row_is_hard_broken_into_row_filling_pieces() {
    // §6: "a word longer than a **full** row is hard-broken at the row edge
    // into successive row-filling pieces, and an implementation that
    // special-cases 'restart the whole word on a new line' diverges as soon as
    // that happens."
    let chunks = wrap_text_chunks("supercalifragilistic", 8, 0);
    assert_eq!(
        chunks
            .iter()
            .map(|chunk| (chunk.text.as_str(), chunk.row_filling))
            .collect::<Vec<_>>(),
        vec![
            ("supercal", true),
            ("ifragili", true),
            ("stic", false),
        ],
    );

    let mut system = TextWindowSystem::new();
    system.set_window_rect(0, 0, 0, 7, 4);
    system.print_wrapped_string("supercalifragilistic");
    let rows: Vec<String> = (0..3)
        .map(|y| {
            (0..8)
                .map(|x| char::from(system.cell(x, y).map(|cell| cell.byte).unwrap_or(b' ')))
                .collect()
        })
        .collect();
    assert_eq!(rows, vec!["supercal", "ifragili", "stic    "]);
}

#[test]
fn an_ordinary_soft_wrap_is_not_flagged_row_filling() {
    // Only the no-break-byte arm takes the R346 route; a line that ended on a
    // remembered space still ends its row.
    let chunks = wrap_text_chunks("the quick brown fox", 10, 0);
    assert!(chunks.iter().all(|chunk| !chunk.row_filling), "{chunks:?}");
}

#[test]
fn text_window_system_defaults_and_preserves_per_window_cursor() {
    let mut system = TextWindowSystem::new();

    assert_eq!(system.active_window_index(), 0);
    for index in 0..TEXT_WINDOW_COUNT {
        assert_eq!(system.window(index), Some(TextWindowDescriptor::default()));
    }

    system.set_window_rect(0, 2, 2, 8, 4);
    system.emit_byte(b'A');
    system.emit_byte(b'B');
    assert_eq!(system.active_cursor(), (2, 0));
    assert_eq!(system.cell(2, 2).unwrap().byte, b'A');
    assert_eq!(system.cell(3, 2).unwrap().byte, b'B');

    system.set_active_window(1);
    system.emit_byte(b'C');
    assert_eq!(system.cell(0, 0).unwrap().byte, b'C');

    system.set_active_window(0);
    assert_eq!(system.active_cursor(), (2, 0));
    system.emit_byte(b'D');
    assert_eq!(system.cell(4, 2).unwrap().byte, b'D');

    system.set_active_window(TEXT_WINDOW_COUNT);
    assert_eq!(system.active_window_index(), 0);
}

#[test]
fn text_window_system_applies_controls_clear_and_cursor_rules() {
    let mut system = TextWindowSystem::new();
    system.set_window_rect(0, 0, 0, 6, 2);
    system.set_active_cursor(2, 1);

    system.emit_byte(TEXT_CTRL_CENTRE_ON);
    system.emit_byte(TEXT_CTRL_INVERSE_TOGGLE);
    system.emit_byte(TEXT_CTRL_UNDERLINE_TOGGLE);
    assert!(system.active_window().centre_enabled());
    assert!(system.active_window().inverse_enabled());
    assert!(system.active_window().underline_enabled());

    system.emit_byte(b'X');
    let styled = system.cell(2, 1).unwrap();
    assert_eq!(styled.byte, b'X');
    assert!(styled.inverse);
    assert!(styled.underline);
    assert_eq!(system.active_cursor(), (3, 1));

    system.emit_byte(TEXT_CTRL_CLEAR_WINDOW);
    assert_eq!(system.cell(2, 1), None);
    assert_eq!(system.active_cursor(), (3, 1));

    system.set_active_cursor(50, 0);
    assert_eq!(system.active_cursor(), (3, 1));
    system.set_active_cursor(1, 0);
    assert_eq!(system.active_cursor(), (1, 0));

    system.set_active_cursor(3, 0);
    system.emit_byte(b'\n');
    assert_eq!(
        system.active_cursor(),
        (0, 1),
        "line feed is a combined carriage return and row advance"
    );
}

