#[test]
fn world_tick_path_classifies_per_spec_branches() {
    // main-loop.md §9
    // Combat scene -> blat-copy regardless of dirty flag.
    assert_eq!(
        world_tick_path(SCENE_COMBAT_TEMPORARY, true),
        WorldTickPath::CombatBlatCopy
    );
    assert_eq!(
        world_tick_path(SCENE_COMBAT_TEMPORARY, false),
        WorldTickPath::CombatBlatCopy
    );
    // 2D scene + dirty flag set -> full rebuild.
    assert_eq!(
        world_tick_path(SCENE_OVERWORLD, true),
        WorldTickPath::ProducerFullRebuild
    );
    assert_eq!(world_tick_path(1, true), WorldTickPath::ProducerFullRebuild);
    assert_eq!(
        world_tick_path(33, true),
        WorldTickPath::ProducerFullRebuild
    );
    // 2D scene + clear dirty flag -> lazy refill.
    assert_eq!(
        world_tick_path(SCENE_OVERWORLD, false),
        WorldTickPath::LazyRefill
    );
    assert_eq!(world_tick_path(1, false), WorldTickPath::LazyRefill);
    assert_eq!(world_tick_path(33, false), WorldTickPath::LazyRefill);
}

#[test]
fn persistent_visibility_rebuild_writes_active_cells_and_preserves_row_scratch() {
    let mut state = test_state(open_grid(), 5, 5);
    state.visibility_dirty = true;
    state.visibility_grid[VIEWPORT_ROW_STRIDE - 1] = 0xA5;
    state.terrain_band[TERRAIN_BAND_ROW_STRIDE - 1] = 0x5A;

    state.refresh_top_down_visibility_buffers(TopDownRenderArea::Town, VIEWPORT_PLAYER_ROW);

    assert!(state.visibility_buffers_ready);
    assert!(!state.visibility_dirty);
    assert_eq!(state.visibility_grid[VIEWPORT_ROW_STRIDE - 1], 0xA5);
    assert_eq!(state.terrain_band[TERRAIN_BAND_ROW_STRIDE - 1], 0x5A);

    let center_grid =
        visibility_grid_active_index(VIEWPORT_PLAYER_ROW, VIEWPORT_PLAYER_COL).unwrap();
    let center_terrain =
        terrain_band_active_index(VIEWPORT_PLAYER_ROW, VIEWPORT_PLAYER_COL).unwrap();
    assert_eq!(state.visibility_grid[center_grid], VISIBILITY_USE_COMPANION);
    assert_eq!(state.terrain_band[center_terrain], PLAYER_TILE);

    let dim_grid = visibility_grid_active_index(2, 3).unwrap();
    let dim_terrain = terrain_band_active_index(2, 3).unwrap();
    assert_eq!(state.visibility_grid[dim_grid], VISIBILITY_DIM_PERIPHERY);
    assert_eq!(state.terrain_band[dim_terrain], 16);
}

#[test]
fn persistent_visibility_lazy_refill_updates_zero_cells_and_restamps_player() {
    let mut state = test_state(open_grid(), 5, 5);
    state.visibility_dirty = true;
    state.refresh_top_down_visibility_buffers(TopDownRenderArea::Town, VIEWPORT_PLAYER_ROW);

    let center_grid =
        visibility_grid_active_index(VIEWPORT_PLAYER_ROW, VIEWPORT_PLAYER_COL).unwrap();
    let center_terrain =
        terrain_band_active_index(VIEWPORT_PLAYER_ROW, VIEWPORT_PLAYER_COL).unwrap();
    state.terrain_band[center_terrain] = 0;
    state.grid[5 * TOWN_GRID_SIDE + 5] = 42;

    state.refresh_top_down_visibility_buffers(TopDownRenderArea::Town, VIEWPORT_PLAYER_ROW);

    assert_eq!(state.visibility_grid[center_grid], VISIBILITY_USE_COMPANION);
    assert_eq!(state.terrain_band[center_terrain], PLAYER_TILE);

    let edge_grid = visibility_grid_active_index(0, 1).unwrap();
    let edge_terrain = terrain_band_active_index(0, 1).unwrap();
    state.visibility_grid[edge_grid] = VISIBILITY_CLEAR;
    state.terrain_band[edge_terrain] = 77;
    // Row 0, column 1.
    state.grid[1] = 88;

    state.refresh_top_down_visibility_buffers(TopDownRenderArea::Town, VIEWPORT_PLAYER_ROW);

    assert_eq!(state.visibility_grid[edge_grid], VISIBILITY_CLEAR);
    assert_eq!(state.terrain_band[edge_terrain], 77);
}

#[test]
fn dungeon_room_clear_bit_position_packs_per_spec() {
    // formats/saved-gam.md §10
    assert_eq!(SAVE_DUNGEON_ROOM_CLEAR_BYTES_PER_DUNGEON, 2);
    assert_eq!(SAVE_DUNGEON_ROOM_CLEAR_ROOMS_PER_DUNGEON, 16);

    // Dungeon 0, room 0 -> byte 0 bit 0.
    assert_eq!(dungeon_room_clear_bit_position(0, 0), Some((0, 0x01)));
    // Dungeon 0, room 7 -> byte 0 bit 7.
    assert_eq!(dungeon_room_clear_bit_position(0, 7), Some((0, 0x80)));
    // Dungeon 0, room 8 -> byte 1 bit 0.
    assert_eq!(dungeon_room_clear_bit_position(0, 8), Some((1, 0x01)));
    // Dungeon 0, room 15 -> byte 1 bit 7.
    assert_eq!(dungeon_room_clear_bit_position(0, 15), Some((1, 0x80)));
    // Dungeon 1, room 0 -> byte 2 bit 0.
    assert_eq!(dungeon_room_clear_bit_position(1, 0), Some((2, 0x01)));
    // Dungeon 7, room 15 -> last bit (byte 15, bit 7).
    assert_eq!(dungeon_room_clear_bit_position(7, 15), Some((15, 0x80)));
    // Out-of-range coordinates.
    assert_eq!(dungeon_room_clear_bit_position(8, 0), None);
    assert_eq!(dungeon_room_clear_bit_position(0, 16), None);
    assert_eq!(dungeon_room_clear_bit_position(255, 255), None);

    // All 128 (dungeon, room) pairs map to distinct bit positions
    // within the 16-byte bitmap.
    use std::collections::HashSet;
    let mut seen = HashSet::new();
    for d in 0u8..8 {
        for r in 0u8..16 {
            let (byte, mask) = dungeon_room_clear_bit_position(d, r).unwrap();
            let bit_index = byte * 8 + (mask.trailing_zeros() as usize);
            assert!(seen.insert(bit_index), "duplicate ({d}, {r})");
            assert!(bit_index < 128);
        }
    }
    assert_eq!(seen.len(), 128);
}

#[test]
fn save_character_field_offsets_match_spec_record() {
    // formats/saved-gam.md §3.1
    assert_eq!(SAVE_CHARACTER_NAME_OFFSET, 0x00);
    assert_eq!(SAVE_CHARACTER_NAME_LEN_BYTES, 9);
    assert_eq!(SAVE_CHARACTER_STRENGTH_OFFSET, 0x0C);
    assert_eq!(SAVE_CHARACTER_DEXTERITY_OFFSET, 0x0D);
    assert_eq!(SAVE_CHARACTER_INTELLIGENCE_OFFSET, 0x0E);
    assert_eq!(SAVE_CHARACTER_MAGIC_POINTS_OFFSET, 0x0F);
    assert_eq!(SAVE_CHARACTER_HP_CURRENT_OFFSET, 0x10);
    assert_eq!(SAVE_CHARACTER_HP_MAX_OFFSET, 0x12);
    assert_eq!(SAVE_CHARACTER_EXPERIENCE_OFFSET, 0x14);
    assert_eq!(SAVE_CHARACTER_LEVEL_OFFSET, 0x16);
    assert_eq!(SAVE_CHARACTER_MONTH_COUNTER_OFFSET, 0x17);
    assert_eq!(SAVE_CHARACTER_DEFENSE_BYTE_OFFSET, 0x18);
    assert_eq!(SAVE_CHARACTER_RECORD_LEN, 32);

    // Slot 0 record begins at file offset 0x0002 (two leading
    // save-image bytes precede the roster).
    assert_eq!(
        save_character_field_offset(0, SAVE_CHARACTER_NAME_OFFSET),
        0x0002
    );
    assert_eq!(
        save_character_field_offset(0, SAVE_CHARACTER_LEVEL_OFFSET),
        0x0002 + 0x16
    );
    // Slot 15 record fits inside the 512-byte roster region.
    assert_eq!(
        save_character_field_offset(15, SAVE_CHARACTER_DEFENSE_BYTE_OFFSET),
        0x0002 + 15 * 32 + 0x18
    );
}

/// `catalogs/item-list.md` Spyglass row / `inventory.md §7`: three
/// conditions — the surface world plane, the outdoor world scene *or a
/// town-class scene*, and the night window `19..=23` / `0..=5`.
///
/// This test previously read `spyglass_usable(scene_byte,
/// sky_has_stars)` and asserted that every non-overworld scene refused.
/// Both halves are withdrawn: the row publishes "the outdoor world scene
/// or a town-class scene ... a broader scene gate than the Sextant's",
/// and the sky-state parameter was a stand-in for the published hour
/// window. The predicate also had no production caller, so the assertion
/// it made was never the assertion the game played.
#[test]
fn spyglass_usable_admits_surface_outdoor_and_town_scenes_at_night() {
    let surface = WorldPlane::Britannia.plane_byte();
    let underworld = WorldPlane::Underworld.plane_byte();

    // Outdoor world scene and every town-family scene are admitted.
    assert!(spyglass_usable(surface, SCENE_OVERWORLD, 20));
    for scene in [SCENE_TOWN_FAMILY_FIRST, 17, SCENE_TOWN_FAMILY_LAST] {
        assert!(
            spyglass_usable(surface, scene, 20),
            "town-class scene {scene} should admit the Spyglass"
        );
    }
    // Dungeon-class and combat-class scenes refuse.
    for scene in [33u8, 40, 127, 0xFF] {
        assert!(
            !spyglass_usable(surface, scene, 20),
            "scene {scene} should refuse the Spyglass"
        );
    }
    // The Underworld is excluded by the same plane condition that
    // excludes it from the Sextant, on every otherwise-admitted scene.
    for scene in [SCENE_OVERWORLD, SCENE_TOWN_FAMILY_FIRST] {
        assert!(!spyglass_usable(underworld, scene, 20));
    }
    // The night window is the Sextant's, not the town-lighting window:
    // hours 5 and 19 are the two the two windows disagree on.
    for hour in 0u8..=23 {
        let expected = hour <= 5 || hour >= 19;
        assert_eq!(
            spyglass_usable(surface, SCENE_OVERWORLD, hour),
            expected,
            "hour {hour}"
        );
        assert_eq!(
            spyglass_usable(surface, SCENE_TOWN_FAMILY_FIRST, hour),
            expected,
            "hour {hour} in a town"
        );
    }
    assert!(spyglass_usable(surface, SCENE_OVERWORLD, 5));
    assert!(spyglass_usable(surface, SCENE_OVERWORLD, 19));
    assert!(!is_town_night_hour(5));
    assert!(!is_town_night_hour(19));
}

