#[test]
fn active_object_composite_dispatches_companion_and_guard_branches() {
    // visibility.md §8
    // `visibility.md §8`: the selector short-circuits to the first entry
    // while the global Negate Time timed effect is active, and otherwise
    // takes the low two bits of the draw. The earlier "active character's
    // class letter is Tinker" rule is withdrawn — there is no
    // character-class input to this selector at all.
    assert_eq!(
        active_object_compositor_variant(true, 3),
        0,
        "Negate Time forces the first variant for every actor"
    );
    for selector in 0u8..=255 {
        assert_eq!(
            active_object_compositor_variant(true, selector),
            0,
            "Negate Time short-circuits regardless of the draw"
        );
        assert_eq!(
            active_object_compositor_variant(false, selector),
            selector & 0x03
        );
    }

    assert_eq!(
        active_object_composite(0xE8, 0x44, 0x10, 0x10, None, None, 5, 0),
        ActiveObjectCompositeResult::Companion(0x44)
    );
    assert_eq!(
        active_object_composite(0xE8, 0x44, VISIBILITY_USE_COMPANION, 0x10, None, None, 5, 0),
        ActiveObjectCompositeResult::Suppress
    );
    assert_eq!(
        active_object_composite(0x80, 0x1D, 0x10, 0x10, None, None, 5, 0),
        ActiveObjectCompositeResult::Companion(0x1D)
    );
    assert_eq!(
        active_object_composite(
            0x5C,
            0x44,
            SINGLE_SPRITE_FAMILY_SEATED_CHAIR_TERRAIN,
            0x10,
            None,
            None,
            5,
            0
        ),
        ActiveObjectCompositeResult::Companion(0x44)
    );
    // `RETRACTIONS.md` R330: "off that terrain the slot falls through to the
    // default helper with its frame byte **reduced by eight**". `0x44` becomes
    // `0x3C`, which is no longer terrain-aware, so it stamps unchanged.
    assert_eq!(
        active_object_composite(0x5C, 0x44, 0x10, 0x10, None, None, 5, 0),
        ActiveObjectCompositeResult::Companion(0x3C)
    );
    // A fall-through whose decremented byte is still terrain-aware reaches the
    // terrain rows with the reduced value: `0x60` becomes `0x58`.
    assert_eq!(
        active_object_composite(0x5C, 0x60, 0x10, 0x57, None, None, 5, 0),
        ActiveObjectCompositeResult::Direct(0x38)
    );
    assert_eq!(
        active_object_composite(0x5C, 0x60, 0x10, 0x10, None, None, 5, 0),
        ActiveObjectCompositeResult::Companion(0x58)
    );
    assert_eq!(
        active_object_composite(
            0x80,
            0x44,
            VISIBILITY_ALREADY_RENDERED,
            0x10,
            None,
            None,
            5,
            0
        ),
        ActiveObjectCompositeResult::Suppress
    );
    assert_eq!(
        active_object_composite(0x80, 0x44, VISIBILITY_HIDDEN, 0x10, None, None, 5, 0),
        ActiveObjectCompositeResult::Suppress
    );
}

#[test]
fn player_slot_survives_the_terrain_aware_suppress_rows() {
    // `visibility.md §8` lists "current terrain `0xEC` or `0x0A` -> suppress
    // the active-object stamp" with no effective-tile qualifier, and
    // `visibility.md §6` names `0x0A` "tropical forest". The shipped
    // passability bitset marks that terrain walkable, so applying the row to
    // slot zero leaves the bare forest tile on screen and the party sprite
    // nowhere - the avatar renders *behind* the forest. `active-objects.md §5`
    // gives slot zero the opposite contract: the table is walked "from slot
    // thirty-one down so slot zero paints on top". Every other slot keeps the
    // published row.
    for terrain in [0x0A, 0xEC] {
        assert_eq!(
            active_object_composite(
                PLAYER_TILE,
                PLAYER_TILE,
                VISIBILITY_CLEAR,
                terrain,
                None,
                None,
                5,
                0
            ),
            ActiveObjectCompositeResult::Suppress,
            "non-player slots keep the published suppress row on terrain {terrain:#04x}"
        );
        assert_eq!(
            composite_active_object_slot(
                false,
                PLAYER_TILE,
                PLAYER_TILE,
                VISIBILITY_CLEAR,
                terrain,
                None,
                None,
                5,
                0
            ),
            ActiveObjectCompositeResult::Suppress
        );
        assert_eq!(
            composite_active_object_slot(
                true,
                PLAYER_TILE,
                PLAYER_TILE,
                VISIBILITY_CLEAR,
                terrain,
                None,
                None,
                5,
                0
            ),
            ActiveObjectCompositeResult::Companion(PLAYER_TILE),
            "slot zero still stamps the party sprite on terrain {terrain:#04x}"
        );
    }

    // The `0x6A`/`0x6B` suppress row is qualified by effective tile, so it
    // never reached the walking party in the first place; the exemption does
    // not change what a monster frame does there.
    assert_eq!(
        active_object_composite(0x80, 0x84, VISIBILITY_CLEAR, 0x6A, None, None, 5, 0),
        ActiveObjectCompositeResult::Suppress
    );

    // `visibility.md §8` step 3: the two cell-state guards run before any class
    // branch and still hide the party. Fog is not a draw-order question.
    for guard in [VISIBILITY_HIDDEN, VISIBILITY_ALREADY_RENDERED] {
        assert_eq!(
            composite_active_object_slot(
                true,
                PLAYER_TILE,
                PLAYER_TILE,
                guard,
                5,
                None,
                None,
                5,
                0
            ),
            ActiveObjectCompositeResult::Suppress
        );
    }

    // Terrain-aware *substitutions* are untouched: `active-objects.md §12`
    // still swaps in the seated/climbing actor byte.
    assert_eq!(
        composite_active_object_slot(
            true,
            PLAYER_TILE,
            PLAYER_TILE,
            VISIBILITY_CLEAR,
            0xC8,
            None,
            None,
            5,
            0
        ),
        ActiveObjectCompositeResult::Companion(0x17)
    );
}

#[test]
fn party_sprite_is_composited_onto_dense_forest_terrain() {
    // End-to-end through the visibility buffers the renderer actually reads:
    // standing on `0x0A` must leave the companion band holding the party's
    // actor byte, not the forest terrain byte.
    const DENSE_FOREST_TILE: u8 = 0x0A;
    let mut grid = open_grid();
    grid[5 * TOWN_GRID_SIDE + 5] = DENSE_FOREST_TILE;
    let mut state = test_state(grid, 5, 5);
    state.visibility_dirty = true;
    state.refresh_top_down_visibility_buffers(TopDownRenderArea::Town, VIEWPORT_PLAYER_ROW);

    let center_grid =
        visibility_grid_active_index(VIEWPORT_PLAYER_ROW, VIEWPORT_PLAYER_COL).unwrap();
    let center_terrain =
        terrain_band_active_index(VIEWPORT_PLAYER_ROW, VIEWPORT_PLAYER_COL).unwrap();
    assert_eq!(state.visibility_grid[center_grid], VISIBILITY_USE_COMPANION);
    assert_eq!(
        state.terrain_band[center_terrain], PLAYER_TILE,
        "the party sprite must draw on top of the forest cell it occupies"
    );
}

#[test]
fn fog_refinement_squared_distance_matches_spec_threshold() {
    // visibility.md §7
    assert_eq!(FOG_REFINE_SQUARED_THRESHOLD, 5);
    // Fold rule: min(coord, 10 - coord).
    assert_eq!(fog_refine_folded_coord(0), 0);
    assert_eq!(fog_refine_folded_coord(5), 5);
    assert_eq!(fog_refine_folded_coord(10), 0);
    assert_eq!(fog_refine_folded_coord(3), 3);
    assert_eq!(fog_refine_folded_coord(7), 3);
    // Centre cell -> distance 0 -> inside core.
    assert_eq!(fog_refine_squared_distance(5, 5), 0);
    assert!(fog_refine_inside_clear_core(5, 5));
    // (5, 4) and (4, 5) -> distance 1 -> inside.
    assert_eq!(fog_refine_squared_distance(5, 4), 1);
    assert_eq!(fog_refine_squared_distance(4, 5), 1);
    // (4, 4) -> 1 + 1 = 2 -> inside.
    assert_eq!(fog_refine_squared_distance(4, 4), 2);
    // (3, 4) -> 4 + 1 = 5 -> still inside (<=5).
    assert_eq!(fog_refine_squared_distance(3, 4), 5);
    assert!(fog_refine_inside_clear_core(3, 4));
    // (3, 3) -> 4 + 4 = 8 -> outside.
    assert_eq!(fog_refine_squared_distance(3, 3), 8);
    assert!(!fog_refine_inside_clear_core(3, 3));
    // Symmetric across the centre — (7, 7) folds to (3, 3).
    assert_eq!(fog_refine_squared_distance(7, 7), 8);
    assert!(!fog_refine_inside_clear_core(7, 7));
}

