#[test]
fn dungeon_room_trigger_loads_selected_dungeon_cbt_record_when_available() {
    let dir = debug_game_dir();
    let scene = DungeonScene::new(35).unwrap();
    let mut record = synthetic_combat_arena_record();
    let source_base =
        DUNGEON_ROOM_SOURCE_ROW * COMBAT_ARENA_ROW_STRIDE + DUNGEON_ROOM_SOURCE_COLUMN;
    for offset in 0..DUNGEON_ROOM_SOURCE_COUNT {
        record[source_base + offset] = 0;
    }
    record[source_base + 2] = 0x44;
    let mut dungeon_cbt = Vec::new();
    for _ in 0..DUNGEON_CBT_RECORDS {
        dungeon_cbt.extend_from_slice(&record);
    }
    fs::write(dir.join(DUNGEON_CBT_FILE), dungeon_cbt).unwrap();
    let mut grid = open_dungeon_record();
    grid[dungeon_cell_index(0, 2, 1)] = 0xf7;
    let mut state = dungeon_state(grid, 0, 1, 1);
    state.area = Area::Dungeon { scene, level: 0 };

    assert_eq!(
        state
            .step_with_game_dir(Direction::East, Some(&dir))
            .unwrap(),
        MoveOutcome::Moved
    );

    assert_eq!(state.grid[dungeon_cell_index(0, 2, 1)], 0xa7);
    assert!(state.combat_active);
    assert_eq!(state.message, DUNGEON_ROOM_ENTRY_NARRATION);
    assert_eq!(state.combat_terrain[0][0], 0x00);
    // `combat.md §5` / `formats/cbt.md §5`: the room helper seats the
    // party first, so the monster descriptor is index six while its
    // renderer record continues from the first record the seated party
    // left free. Follow the descriptor's link byte, which is "the
    // authoritative pairing in both directions". The stock roster is one
    // live member, so that record is one.
    assert!(!state.combat_actors[6].is_empty());
    let monster_record = usize::from(state.combat_actors[6].active_object_slot);
    assert_eq!(monster_record, 1);
    assert_eq!(state.active_objects[monster_record].tile, 0x44);
    assert_eq!(
        (
            state.active_objects[monster_record].x,
            state.active_objects[monster_record].y
        ),
        (2, 13)
    );
    assert!(!dungeon_room_clear_bit_is_set(
        &state.dungeon_room_clear_bitmap,
        scene,
        7
    ));
    assert_eq!(
        state
            .combat_frame_snapshot
            .as_ref()
            .and_then(|snapshot| snapshot.dungeon_room_clear_on_success)
            .map(|pending| (pending.scene, pending.room_slot)),
        Some((scene, 7))
    );
    let application = state.apply_combat_round_loop_exit(CombatRoundLoopExit::LeaveCombat);
    assert_eq!(application.result_code, COMBAT_ROUND_RESULT_SUCCESS);
    assert!(dungeon_room_clear_bit_is_set(
        &state.dungeon_room_clear_bitmap,
        scene,
        7
    ));
    let _ = fs::remove_dir_all(dir);
}

