#[test]
fn spell_indoor_absorbs_matches_spec_short_circuits() {
    // catalogs/spell-list.md §4
    // Stonegate absorbs unconditionally
    assert!(spell_indoor_absorbs(false, true, true));
    assert!(spell_indoor_absorbs(false, false, true));
    assert!(spell_indoor_absorbs(true, true, true));
    // Blackthorn absorbs only without the Crown
    assert!(spell_indoor_absorbs(true, false, false));
    assert!(!spell_indoor_absorbs(true, true, false));
    // Other indoor scenes pass through
    assert!(!spell_indoor_absorbs(false, false, false));
    assert!(!spell_indoor_absorbs(false, true, false));
}

#[test]
fn rune_syllable_vocabulary_matches_spec_table() {
    // magic.md §3
    assert_eq!(RUNE_SYLLABLE_VOCABULARY.len(), 24);
    assert_eq!(RUNE_SYLLABLE_VOCABULARY[0], "An");
    assert_eq!(RUNE_SYLLABLE_VOCABULARY[7], "Hur");
    assert_eq!(RUNE_SYLLABLE_VOCABULARY[23], "Zu");
    // Resident syllables accept (case-insensitive)
    assert!(is_resident_rune_syllable("An"));
    assert!(is_resident_rune_syllable("an"));
    assert!(is_resident_rune_syllable("MANI"));
    assert!(is_resident_rune_syllable("Vas"));
    assert!(is_resident_rune_syllable("Quas"));
    assert!(is_resident_rune_syllable("Xen"));
    assert!(is_resident_rune_syllable("Ylem"));
    // Older Ultima lore syllables are rejected
    assert!(!is_resident_rune_syllable("Jux"));
    assert!(!is_resident_rune_syllable("Ort"));
    assert!(!is_resident_rune_syllable("jux"));
    assert!(!is_resident_rune_syllable(""));
    assert!(!is_resident_rune_syllable("Foo"));
    // Cross-check: every spec entry is accepted
    for syllable in RUNE_SYLLABLE_VOCABULARY {
        assert!(is_resident_rune_syllable(syllable));
    }
}

#[test]
fn spell_common_name_covers_all_48_indices() {
    // magic.md §4
    assert_eq!(SPELL_CIRCLE_COUNT, 8);
    assert_eq!(SPELLS_PER_CIRCLE, 6);
    assert_eq!(SPELL_COUNT, SPELL_CIRCLE_COUNT * SPELLS_PER_CIRCLE);

    let expected_first_per_circle = [
        "Light",
        "Open",
        "Great Light",
        "Dispel Field",
        "Swarm",
        "Tremor",
        "Invisibility",
        "Resurrect",
    ];
    for (circle, name) in expected_first_per_circle.iter().enumerate() {
        let idx = circle * SPELLS_PER_CIRCLE;
        assert_eq!(spell_common_name(idx), Some(*name));
    }
    let expected_last_per_circle = [
        "Vanish",
        "Create Food",
        "Blink",
        "Reveal",
        "Quickness",
        "Polymorph",
        "Cause Fear",
        "Negate Time",
    ];
    for (circle, name) in expected_last_per_circle.iter().enumerate() {
        let idx = circle * SPELLS_PER_CIRCLE + (SPELLS_PER_CIRCLE - 1);
        assert_eq!(spell_common_name(idx), Some(*name));
    }
    // Every index 0..=47 returns Some
    for i in 0..SPELL_COUNT {
        assert!(spell_common_name(i).is_some(), "missing name {i}");
    }
    assert_eq!(spell_common_name(48), None);
    assert_eq!(spell_common_name(255), None);
}

#[test]
fn cast_dispatcher_gate_matches_spec_order_and_messages() {
    // magic.md §7
    // Scene gate first: Not here! before charge consumption.
    let r = cast_dispatcher_gate(false, 0, 0, 0, 0);
    assert_eq!(r, CastGateOutcome::NotHere);
    assert!(!r.consumed_charge());
    assert!(!r.consumed_mana());
    assert_eq!(r.message(), "Not here!");

    // No charges: None mixed!, no charge spent.
    let r = cast_dispatcher_gate(true, 0, 99, 8, 1);
    assert_eq!(r, CastGateOutcome::NoneMixed);
    assert!(!r.consumed_charge());
    assert!(!r.consumed_mana());
    assert_eq!(r.message(), "None mixed!");

    // Mana too low: charge spent, mana not.
    let r = cast_dispatcher_gate(true, 1, 2, 8, 5);
    assert_eq!(r, CastGateOutcome::ManaTooLowChargeOnly);
    assert!(r.consumed_charge());
    assert!(!r.consumed_mana());
    assert_eq!(r.message(), "M.P. too low!");

    // Level too low: charge AND mana spent.
    let r = cast_dispatcher_gate(true, 1, 99, 1, 5);
    assert_eq!(r, CastGateOutcome::LevelTooLowChargeAndMana);
    assert!(r.consumed_charge());
    assert!(r.consumed_mana());
    assert_eq!(r.message(), "M.P. too low!");

    // All gates pass.
    let r = cast_dispatcher_gate(true, 1, 99, 8, 5);
    assert_eq!(r, CastGateOutcome::Cast);
    assert!(r.consumed_charge());
    assert!(r.consumed_mana());

    // Heal amount: 0..=60 roll, halved, zero -> 1.
    assert_eq!(heal_spell_amount_from_raw_roll_u8(0), 1);
    assert_eq!(heal_spell_amount_from_raw_roll_u8(1), 1);
    assert_eq!(heal_spell_amount_from_raw_roll_u8(2), 1);
    assert_eq!(heal_spell_amount_from_raw_roll_u8(3), 1);
    assert_eq!(heal_spell_amount_from_raw_roll_u8(4), 2);
    assert_eq!(heal_spell_amount_from_raw_roll_u8(60), 30);
}

#[test]
fn summoned_creatures_reach_the_command_handler_and_are_prompted_by_it() {
    // combat.md §6.1a writer 3: summoned creatures "are still placed
    // through the ordinary monster placement path, so their class byte
    // is the monster-side one - but the bit **does** hand the creature
    // to the player's prompt: a monster-side slot carrying it is
    // dispatched to the keystroke/command path, not to the automatic
    // driver". magic.md, Summoning and conjuration, carries the matching
    // correction: "That bit **is** a transfer of control ... a
    // monster-side slot carrying the bit fails the self-acting test, so
    // the round walker sends it to the keystroke/command path instead of
    // to the automatic actor driver." RETRACTIONS.md R354 withdraws the
    // earlier "monster AI drives its turns ... the player never gets to
    // move it" reading this test used to assert.
    //
    // combat.md §6.1a: "The walker sends the group ordinarily occupied
    // by seated party members to the keystroke/command path (Section 8)
    // and the other group to the automatic actor driver (Section 9). A
    // party-side actor carrying this bit therefore takes its turns
    // through the automatic driver instead of the player's prompt."
    let descriptor = |flags: u8, owner: u8| CombatActorDescriptor {
        hp_or_wound: 10,
        base_step: 1,
        flags,
        owner_target_class: owner,
        active_object_slot: 0,
        phase_counter: 0,
        x: 1,
        y: 1,
    };

    // An ordinary seated party member takes the keystroke path.
    let party = descriptor(COMBAT_ACTOR_FLAG_SELECTABLE_80, 0);
    assert!(combat_slot_takes_player_command_path(0, party));
    assert!(combat_slot_takes_player_command_path(
        COMBAT_PARTY_ACTOR_SLOTS - 1,
        party
    ));

    // Sword of Chaos / possession / Charm on a party-side slot: the
    // controlled bit moves it to the automatic driver, not the prompt.
    let controlled_party = descriptor(
        COMBAT_ACTOR_FLAG_SELECTABLE_80 | COMBAT_ACTOR_FLAG_CONTROLLED,
        0,
    );
    assert!(!combat_slot_takes_player_command_path(0, controlled_party));

    // combat.md §6.1: "Monster and object descriptors never carry"
    // 0x80; an ordinary monster is the hostile placement tag and is
    // driven by monster AI.
    let monster = descriptor(combat_monster_placement_flags(20), 20);
    assert_eq!(monster.flags, COMBAT_ACTOR_FLAG_SELECTABLE_40);
    assert!(!combat_slot_takes_player_command_path(
        COMBAT_PARTY_ACTOR_SLOTS,
        monster
    ));

    // Conjure / Swarm / Summon stamp the summoned-actor flags into a
    // monster-side slot: 0x40 | 0x01, never 0x80. §16.1 resolves that
    // descriptor to group 0, and "Group-0 actors enter the combined
    // command handler", so every monster-side slot carrying the bit
    // reaches the keystroke path.
    let summoned = descriptor(combat_summoned_actor_flags(20), 20);
    assert_eq!(
        summoned.flags,
        COMBAT_ACTOR_FLAG_SELECTABLE_40 | COMBAT_ACTOR_FLAG_CONTROLLED
    );
    assert!(summoned.is_controlled());
    assert_eq!(
        resolve_combat_target_group_for_actor(summoned, COMBAT_PARTY_ACTOR_SLOTS, None),
        COMBAT_TARGET_GROUP_PARTY
    );
    for slot in COMBAT_PARTY_ACTOR_SLOTS..COMBAT_ACTOR_SLOTS {
        assert!(
            combat_slot_takes_player_command_path(slot, summoned),
            "summoned creature in slot {slot} missed the player command path"
        );
    }

    // A dead or empty descriptor takes no path at all, whatever its group:
    // the group helper answers "party" for a dead actor, and that must not
    // be read as a dispatch decision.
    let dead_summoned = descriptor(
        combat_summoned_actor_flags(20) | COMBAT_ACTOR_FLAG_MARKED_DEAD,
        20,
    );
    assert!(!combat_slot_takes_player_command_path(
        COMBAT_PARTY_ACTOR_SLOTS,
        dead_summoned
    ));

    // Summon's rebound branch leaves the bit clear, and that Daemon is
    // "really hostile and AI-driven" (magic.md, Summoning and
    // conjuration).
    let rebound = descriptor(combat_monster_placement_flags(38), 38);
    for slot in COMBAT_PARTY_ACTOR_SLOTS..COMBAT_ACTOR_SLOTS {
        assert!(!combat_slot_takes_player_command_path(slot, rebound));
    }

    // combat.md §9: the traitor-roster override applies "for both the
    // friendly-fire filter and the player-versus-AI dispatch gate".
    let traitor = descriptor(COMBAT_ACTOR_FLAG_SELECTABLE_80, TRAITOR_ROSTER_RECORD);
    assert!(!combat_slot_takes_player_command_path(1, traitor));

    // `combat.md` §16.1: the handler "**prompts, and never synthesizes**.
    // Its one gate is the active-player sentinel: while the sentinel is
    // unset ... **every** group-0 slot is prompted." The keystroke gate is
    // therefore exactly the dispatch gate plus that sentinel, and the
    // summoned/charmed monster is prompted like a party member.
    //
    // *(The withdrawn assertions - that the prompt was narrower than the
    // dispatch path by exactly the summoned/charmed monster - implemented
    // §16.1's "still synthesizes an automatic action" clause;
    // `RETRACTIONS.md` R377 and R378 withdraw it.)*
    assert!(combat_slot_prompted_by_player_command_handler(None, 0, party));
    assert!(!combat_slot_prompted_by_player_command_handler(
        None,
        0,
        controlled_party
    ));
    for slot in COMBAT_PARTY_ACTOR_SLOTS..COMBAT_ACTOR_SLOTS {
        assert!(
            combat_slot_prompted_by_player_command_handler(None, slot, summoned),
            "summoned creature in slot {slot} was refused the prompt"
        );
        // "while a character is selected with `1`-`6`, only the party-side
        // slot that sentinel names is prompted and every other group-0 slot,
        // party or monster, is skipped without a banner, a keystroke or an
        // action."
        assert!(!combat_slot_prompted_by_player_command_handler(
            Some(0),
            slot,
            summoned
        ));
    }
    assert!(combat_slot_prompted_by_player_command_handler(
        Some(0),
        0,
        party
    ));
    assert!(!combat_slot_prompted_by_player_command_handler(
        Some(1),
        0,
        party
    ));
}

#[test]
fn combat_combatant_capacity_matches_spec() {
    // active-objects.md §7: "Within combat there is no reserved
    // player slot and no twenty-six-combatant cap; earlier drafts
    // of this section claimed both and were wrong. ... The hard
    // limits are the thirty-two records themselves and, for terrain
    // combat, the sixteen arena placement slots; a terrain
    // encounter can never place more than sixteen monsters."
    assert_eq!(COMBAT_ACTOR_SLOTS, 32);
    assert_eq!(CBT_PLACEMENT_SLOT_COUNT, 16);
    // "a full party occupies records zero through five" - the party
    // takes the first free records, it does not reserve slot zero
    // for a player figure.
    assert_eq!(COMBAT_PARTY_ACTOR_SLOTS, 6);
    assert!(COMBAT_PARTY_ACTOR_SLOTS <= COMBAT_ACTOR_SLOTS);
    assert!(CBT_PLACEMENT_SLOT_COUNT <= COMBAT_ACTOR_SLOTS - COMBAT_PARTY_ACTOR_SLOTS);
}

#[test]
fn first_monster_ability_picks_in_spec_order() {
    // combat.md §9
    assert_eq!(MONSTER_ABILITY_POSSESS, 0x0040);
    assert_eq!(MONSTER_ABILITY_BLINK, 0x0800);
    assert_eq!(MONSTER_ABILITY_SUMMON_DAEMON, 0x0400);
    // No ability bits
    assert_eq!(first_monster_ability(0), None);
    assert_eq!(
        first_monster_ability(0xFFFF & !(0x0040 | 0x0400 | 0x0800)),
        None
    );
    // One bit at a time
    assert_eq!(
        first_monster_ability(MONSTER_ABILITY_POSSESS),
        Some(MonsterAbility::Possess)
    );
    assert_eq!(
        first_monster_ability(MONSTER_ABILITY_BLINK),
        Some(MonsterAbility::Blink)
    );
    assert_eq!(
        first_monster_ability(MONSTER_ABILITY_SUMMON_DAEMON),
        Some(MonsterAbility::SummonDaemon)
    );
    // Multiple bits — possess wins, then blink, then summon
    assert_eq!(
        first_monster_ability(MONSTER_ABILITY_POSSESS | MONSTER_ABILITY_BLINK),
        Some(MonsterAbility::Possess)
    );
    assert_eq!(
        first_monster_ability(
            MONSTER_ABILITY_POSSESS | MONSTER_ABILITY_BLINK | MONSTER_ABILITY_SUMMON_DAEMON
        ),
        Some(MonsterAbility::Possess)
    );
    assert_eq!(
        first_monster_ability(MONSTER_ABILITY_BLINK | MONSTER_ABILITY_SUMMON_DAEMON),
        Some(MonsterAbility::Blink)
    );
}

#[test]
fn tile_super_category_splits_per_spec() {
    // catalogs/tile-catalog.md §2
    // Map terrain band 0..=159
    assert_eq!(tile_super_category(0), Some(TileSuperCategory::MapTerrain));
    assert_eq!(tile_super_category(50), Some(TileSuperCategory::MapTerrain));
    assert_eq!(
        tile_super_category(159),
        Some(TileSuperCategory::MapTerrain)
    );
    // Actor band 160..=511
    assert_eq!(tile_super_category(160), Some(TileSuperCategory::Actor));
    assert_eq!(tile_super_category(256), Some(TileSuperCategory::Actor));
    assert_eq!(tile_super_category(511), Some(TileSuperCategory::Actor));
    // Above the published sheet
    assert_eq!(tile_super_category(512), None);
    assert_eq!(tile_super_category(65535), None);
}

