#[test]
fn active_object_should_prune_is_a_square_window_from_the_scroll_base() {
    // active-objects.md §8.1: the pass "compares the slot's stored X
    // and Y against the current scroll base - the top-left corner of
    // the loaded window - and keeps the slot only when both
    // differences are in 0..=31. Failing either axis releases the slot."
    //
    // The base is a CORNER, not a centre: the window runs forward from
    // it. An earlier revision of this test asserted a centred +/-32
    // band, which §8.1 refutes.
    assert_eq!(ACTIVE_OBJECT_PRUNE_WINDOW_EXTENT, 31);
    assert_eq!(ACTIVE_OBJECT_SAVE_BYTES, 256);
    // Inside the window (forward from the base on both axes): keep.
    assert!(!active_object_should_prune(100, 100, 100, 100));
    assert!(!active_object_should_prune(131, 100, 100, 100));
    assert!(!active_object_should_prune(100, 131, 100, 100));
    assert!(!active_object_should_prune(131, 131, 100, 100));
    // One past the bound on either axis: prune.
    assert!(active_object_should_prune(132, 100, 100, 100));
    assert!(active_object_should_prune(100, 132, 100, 100));
    // Behind the base is outside the window, not inside a centred band.
    assert!(active_object_should_prune(99, 100, 100, 100));
    assert!(active_object_should_prune(100, 99, 100, 100));
    assert!(active_object_should_prune(68, 100, 100, 100));
    assert!(active_object_should_prune(100, 68, 100, 100));
}

#[test]
fn active_object_prune_type_classifier_matches_every_published_byte_range() {
    // active-objects.md §8.1 publishes a complete 256-value table. Keep this
    // exhaustive so a broadened semantic shortcut cannot silently reappear.
    for type_byte in u8::MIN..=u8::MAX {
        let expected = (0x2c..=0x2f).contains(&type_byte)
            || (0x80..=0xb3).contains(&type_byte)
            || (0xb8..=0xe7).contains(&type_byte)
            || (0xec..=0xff).contains(&type_byte);
        assert_eq!(
            active_object_type_is_prunable(type_byte),
            expected,
            "type byte {type_byte:#04x}"
        );
    }

    // Named boundary consequences from the spec.
    for parked_vehicle in [0x10, 0x11, 0x1b, 0x24, 0x2b] {
        assert!(!active_object_type_is_prunable(parked_vehicle));
    }
    assert!(active_object_type_is_prunable(0x2c));
    assert!(!active_object_type_is_prunable(0x30));
    assert!(!active_object_type_is_prunable(0x7f));
    assert!(!active_object_type_is_prunable(0xb5));
}

#[test]
fn active_object_should_prune_keeps_the_window_corners() {
    // active-objects.md §8.1: "It is a square window, not a radius.
    // The two axes are tested separately and independently against the
    // same bound. There is no distance computation, no hypotenuse and
    // no disc. Naming this quantity a radius invites an implementation
    // to compute a Euclidean or squared distance, which prunes the
    // corners of the window that the original keeps."
    //
    // The far corner is 31 out on both axes: Euclidean ~43.84 and
    // squared 1922 both exceed 31, so either metric would prune it.
    assert!(!active_object_should_prune(131, 131, 100, 100));
    // And the corner is genuinely the extreme: one further on either
    // axis leaves the window.
    assert!(active_object_should_prune(132, 131, 100, 100));
    assert!(active_object_should_prune(131, 132, 100, 100));
}

#[test]
fn active_object_should_prune_wraps_in_unsigned_eight_bit_arithmetic() {
    // active-objects.md §8.1: "The difference is formed in unsigned
    // eight-bit arithmetic against the scroll base, so it wraps
    // naturally with the 256-cell coordinate space rather than needing
    // a special case at the map seam. An implementation using signed
    // or wider arithmetic will mis-handle objects across the wrap."
    //
    // Scroll base near the top of the coordinate space: the window
    // runs off the end and resumes at zero.
    assert!(!active_object_should_prune(240, 240, 240, 240));
    assert!(!active_object_should_prune(255, 255, 240, 240));
    assert!(!active_object_should_prune(0, 0, 240, 240)); // 0 - 240 = 16
    assert!(!active_object_should_prune(15, 15, 240, 240)); // 15 - 240 = 31
    // One cell past the wrapped bound.
    assert!(active_object_should_prune(16, 15, 240, 240));
    assert!(active_object_should_prune(15, 16, 240, 240));
    // Signed subtraction would make this look like -239 (inside a
    // +/-32 band on the wrong side); unsigned makes it 17.
    assert!(active_object_should_prune(1, 1, 240, 240) == false);
    assert!(active_object_should_prune(240, 1, 1, 1)); // 240 - 1 = 239
}

#[test]
fn active_object_eviction_phase_matches_spec_cascade() {
    // active-objects.md §4
    // Empty slot is always phase 1.
    assert_eq!(active_object_eviction_phase(0x00, true), Some(1));
    assert_eq!(active_object_eviction_phase(0x00, false), Some(1));

    // 0x01..=0x0F low-priority scenery
    assert_eq!(active_object_eviction_phase(0x01, true), Some(2));
    assert_eq!(active_object_eviction_phase(0x0F, true), Some(2));
    assert_eq!(active_object_eviction_phase(0x01, false), Some(6));

    // 0x80..=0xFF monsters/dynamic actors (except 0xB5)
    assert_eq!(active_object_eviction_phase(0x80, true), Some(3));
    assert_eq!(active_object_eviction_phase(0xFF, true), Some(3));
    assert_eq!(active_object_eviction_phase(0x80, false), Some(7));
    assert_eq!(active_object_eviction_phase(0xB5, true), None);
    assert_eq!(active_object_eviction_phase(0xB5, false), None);

    // 0x10..=0x11 door/fixture-like
    assert_eq!(active_object_eviction_phase(0x10, true), Some(4));
    assert_eq!(active_object_eviction_phase(0x11, true), Some(4));
    assert_eq!(active_object_eviction_phase(0x10, false), Some(8));

    // 0x30..=0x7F items/chests
    assert_eq!(active_object_eviction_phase(0x30, true), Some(5));
    assert_eq!(active_object_eviction_phase(0x7F, true), Some(5));
    assert_eq!(active_object_eviction_phase(0x30, false), Some(9));

    // 0x12..=0x1F NPC/person ranges and 0x20..=0x2F vehicle ranges
    // are protected from off-screen phases but eligible for the
    // last-resort phase 10.
    assert_eq!(active_object_eviction_phase(0x12, true), Some(10));
    assert_eq!(active_object_eviction_phase(0x1F, true), Some(10));
    assert_eq!(active_object_eviction_phase(0x20, true), Some(10));
    assert_eq!(active_object_eviction_phase(0x2F, true), Some(10));
    assert_eq!(active_object_eviction_phase(0x20, false), Some(10));
}

#[test]
fn chargen_questionnaire_always_floors_strength_to_twenty() {
    // chargen.md §7: max STR contribution is 2 per question and there
    // are 7 questions, so the floor always fires.
    assert_eq!(CHARGEN_STR_FLOOR, 20);
    assert_eq!(CHARGEN_STARTING_PARTY_SIZE, 3);

    // Empty winners list: STR should still be floored to 20.
    //
    // `chargen.md §7` retraction: the dexterity tally "starts from the
    // shipped seed record's dexterity of `15`", so an unwinnable
    // questionnaire still commits DEX 15 - "Dexterity itself is still
    // written with no floor of its own - the 15 is where the tally starts,
    // not a clamp applied at commit." §7 publishes no upper bound for
    // questionnaire dexterity, so none is asserted here.
    let stats = chargen_stats_from_winners(&[]);
    assert_eq!(stats.strength, CHARGEN_STR_FLOOR);
    assert_eq!(CHARGEN_SEED_DEXTERITY, 15);
    assert_eq!(stats.dexterity, CHARGEN_SEED_DEXTERITY);
    assert_eq!(stats.intelligence, 0);

    // `combat.md §5.1`: "A questionnaire Avatar therefore enters play with
    // dexterity 15 or better, giving a phase counter of **21 or less**."
    for virtues in [
        vec![],
        vec![ShrineVirtue::Humility; 7],
        vec![ShrineVirtue::Compassion; 7],
        vec![ShrineVirtue::Spirituality; 7],
    ] {
        let stats = chargen_stats_from_winners(&virtues);
        assert!(stats.dexterity >= CHARGEN_SEED_DEXTERITY);
        assert!(COMBAT_PLACEMENT_PHASE_BASE - stats.dexterity <= 21);
    }

    // Worst-case STR contribution (any seven Spirituality wins):
    // chargen_virtue_stat_delta(Spirituality) is INT-only, so STR
    // remains 0 before the floor.
    let all_spirituality = vec![ShrineVirtue::Spirituality; 7];
    let stats = chargen_stats_from_winners(&all_spirituality);
    assert_eq!(stats.strength, CHARGEN_STR_FLOOR);

    // Best-case STR contribution: any seven full-STR virtues should
    // still floor the result, since 7*max delta < 20 only if delta<3.
    // Either way, the result must be >= floor.
    for v in [
        ShrineVirtue::Honesty,
        ShrineVirtue::Compassion,
        ShrineVirtue::Valor,
        ShrineVirtue::Justice,
        ShrineVirtue::Sacrifice,
        ShrineVirtue::Honor,
        ShrineVirtue::Spirituality,
        ShrineVirtue::Humility,
    ] {
        let stats = chargen_stats_from_winners(&vec![v; 7]);
        assert!(stats.strength >= CHARGEN_STR_FLOOR);
    }
}

